window.BSP_EQUATION_PREVIEWS = {"ch04_systems/01_what_is_a_system.html#eq-3-1": {"tex": "\\begin{equation*}\ny = \\mathcal{T}\\{x\\}, \\tag{3.1}\n\\end{equation*}"}, "ch04_systems/01_what_is_a_system.html#eq-3-2": {"tex": "\\begin{equation*}\nRC\\,\\frac{dy}{dt} + y(t) = x(t). \\tag{3.2}\n\\end{equation*}"}, "ch04_systems/01_what_is_a_system.html#eq-3-3": {"tex": "\\begin{equation*}\ny[n] = \\frac{1}{M}\\sum_{k=0}^{M-1} x[n-k]. \\tag{3.3}\n\\end{equation*}"}, "ch04_systems/01_what_is_a_system.html#eq-3-4": {"tex": "\\begin{equation*}\ny[n] = x[n] - x[n-1] \\tag{3.4}\n\\end{equation*}"}, "ch04_systems/01_what_is_a_system.html#eq-3-5": {"tex": "\\begin{equation*}\n\\frac{dC}{dt} = -k\\,C(t) + \\frac{r(t)}{V}. \\tag{3.5}\n\\end{equation*}"}, "ch04_systems/01_what_is_a_system.html#eq-3-6": {"tex": "\\begin{equation*}\n\\begin{aligned}\n\\frac{dC}{C} &= -k\\,dt \\\\[2pt]\n\\ln C(t) - \\ln C(0) &= -k\\,t \\\\[2pt]\nC(t) &= \\frac{D}{V}\\,e^{-kt}, \\qquad t \\ge 0.\n\\end{aligned} \\tag{3.6}\n\\end{equation*}"}, "ch04_systems/01_what_is_a_system.html#eq-3-7": {"tex": "\\begin{equation*}\nt_{1/2} = \\frac{\\ln 2}{k}. \\tag{3.7}\n\\end{equation*}"}, "ch04_systems/01_what_is_a_system.html#eq-3-8": {"tex": "\\begin{equation*}\n\\begin{aligned}\nC_{\\text{peak}, n} &= \\frac{D}{V}\\sum_{m=0}^{n} e^{-k(n-m)\\tau}\n = \\frac{D}{V}\\sum_{i=0}^{n} \\rho^{\\,i}, \\qquad \\rho = e^{-k\\tau} \\\\[4pt]\n&= \\frac{D}{V}\\,\\frac{1 - \\rho^{\\,n+1}}{1 - \\rho}\n\\;\\xrightarrow{\\;n\\to\\infty\\;}\\; \\frac{D}{V}\\,\\frac{1}{1 - \\rho}.\n\\end{aligned} \\tag{3.8}\n\\end{equation*}"}, "ch04_systems/01_what_is_a_system.html#eq-3-9": {"tex": "\\begin{equation*}\nC[n] = a\\,C[n-1] + \\frac{d[n]}{V}. \\tag{3.9}\n\\end{equation*}"}, "ch04_systems/01_what_is_a_system.html#eq-3-10": {"tex": "\\begin{equation*}\n\\tau_c\\,\\frac{dp}{dt} = -p(t) + d(t) + u(t), \\tag{3.10}\n\\end{equation*}"}, "ch04_systems/01_what_is_a_system.html#eq-3-11": {"tex": "\\begin{equation*}\nu(t) = -K\\,p(t - \\Delta). \\tag{3.11}\n\\end{equation*}"}, "ch04_systems/01_what_is_a_system.html#eq-3-12": {"tex": "\\begin{equation*}\n\\begin{aligned}\n0 &= -p_{\\text{ss}} + d_0 - K\\,p_{\\text{ss}} \\\\[2pt]\np_{\\text{ss}} &= \\frac{d_0}{1 + K}.\n\\end{aligned} \\tag{3.12}\n\\end{equation*}"}, "ch04_systems/01_what_is_a_system.html#eq-3-13": {"tex": "\\begin{equation*}\n\\begin{aligned}\ny &= G\\,e = G\\,(x - H\\,y) \\\\[2pt]\ny\\,(1 + GH) &= G\\,x \\\\[2pt]\ny &= \\frac{G}{1 + GH}\\,x.\n\\end{aligned} \\tag{3.13}\n\\end{equation*}"}, "ch04_systems/01_what_is_a_system.html#sec-3-1-1": {"tex": "\\begin{equation*}\ny = \\mathcal{T}\\{x\\}, \\tag{3.1}\n\\end{equation*}"}, "ch04_systems/01_what_is_a_system.html#sec-3-1-2": {"tex": "y(t) = G\\,x(t)."}, "ch04_systems/01_what_is_a_system.html#sec-3-1-3": {"tex": "\\frac{dA}{dt} = r(t) - k\\,A(t),"}, "ch04_systems/01_what_is_a_system.html#sec-3-1-4": {"tex": "\\begin{equation*}\n\\tau_c\\,\\frac{dp}{dt} = -p(t) + d(t) + u(t), \\tag{3.10}\n\\end{equation*}"}, "ch04_systems/01_what_is_a_system.html#sec-3-1-5": {"tex": "\\begin{equation*}\n\\begin{aligned}\ny &= G\\,e = G\\,(x - H\\,y) \\\\[2pt]\ny\\,(1 + GH) &= G\\,x \\\\[2pt]\ny &= \\frac{G}{1 + GH}\\,x.\n\\end{aligned} \\tag{3.13}\n\\end{equation*}"}, "ch04_systems/02_linearity.html#eq-3-14": {"tex": "\\begin{equation*}\n\\mathcal{T}\\{a_1 x_1 + a_2 x_2\\} = a_1\\,\\mathcal{T}\\{x_1\\} + a_2\\,\\mathcal{T}\\{x_2\\}. \\tag{3.14}\n\\end{equation*}"}, "ch04_systems/02_linearity.html#eq-3-15": {"tex": "\\begin{equation*}\n\\mathcal{T}\\left\\{\\sum_{k=1}^{K} a_k\\,x_k\\right\\} = \\sum_{k=1}^{K} a_k\\,\\mathcal{T}\\{x_k\\}. \\tag{3.15}\n\\end{equation*}"}, "ch04_systems/02_linearity.html#eq-3-16": {"tex": "\\begin{equation*}\ny(t) = A^2\\cos^2(\\omega_0 t) = \\frac{A^2}{2} + \\frac{A^2}{2}\\cos(2\\omega_0 t). \\tag{3.16}\n\\end{equation*}"}, "ch04_systems/02_linearity.html#eq-3-17": {"tex": "\\begin{equation*}\n\\begin{aligned}\n\\cos^3\\theta &= \\cos\\theta\\cdot\\tfrac{1}{2}(1 + \\cos 2\\theta) = \\tfrac{1}{2}\\cos\\theta + \\tfrac{1}{2}\\cos\\theta\\cos 2\\theta \\\\[2pt]\n&= \\tfrac{1}{2}\\cos\\theta + \\tfrac{1}{4}\\big(\\cos\\theta + \\cos 3\\theta\\big)\n= \\tfrac{3}{4}\\cos\\theta + \\tfrac{1}{4}\\cos 3\\theta .\n\\end{aligned} \\tag{3.17}\n\\end{equation*}"}, "ch04_systems/02_linearity.html#eq-3-18": {"tex": "\\begin{equation*}\n2A_1A_2\\cos(\\omega_1 t)\\cos(\\omega_2 t) = A_1A_2\\cos\\big((\\omega_1 - \\omega_2)t\\big) + A_1A_2\\cos\\big((\\omega_1 + \\omega_2)t\\big). \\tag{3.18}\n\\end{equation*}"}, "ch04_systems/02_linearity.html#sec-3-2-1": {"tex": "\\mathcal{T}\\{x_1 + x_2\\} = \\mathcal{T}\\{x_1\\} + \\mathcal{T}\\{x_2\\} = y_1 + y_2 \\quad\\text{for all } x_1, x_2 ."}, "ch04_systems/02_linearity.html#sec-3-2-2": {"tex": "\\begin{aligned}\ny_3(t) = x_3^2(t) &= \\big(a\\,x_1(t) + b\\,x_2(t)\\big)^2 \\\\[2pt]\n&= a^2 x_1^2(t) + 2ab\\,x_1(t)\\,x_2(t) + b^2 x_2^2(t).\n\\end{aligned}"}, "ch04_systems/02_linearity.html#sec-3-2-3": {"tex": "\\varepsilon = \\frac{\\lVert \\mathbf{u} - \\mathbf{v} \\rVert}{\\max\\big(\\lVert \\mathbf{u}\\rVert, \\lVert \\mathbf{v}\\rVert\\big)},"}, "ch04_systems/02_linearity.html#sec-3-2-5": {"tex": "y[n] = x[n] - \\frac{1}{217}\\sum_{k=-108}^{108} x[n - k]."}, "ch04_systems/02_linearity.html#sec-3-2-6": {"tex": "\\begin{equation*}\ny(t) = A^2\\cos^2(\\omega_0 t) = \\frac{A^2}{2} + \\frac{A^2}{2}\\cos(2\\omega_0 t). \\tag{3.16}\n\\end{equation*}"}, "ch05_convolution/01_impulse_representation.html#eq-4-1": {"tex": "\\begin{equation*}\nx[n]\\,\\delta[n-k] = x[k]\\,\\delta[n-k]. \\tag{4.1}\n\\end{equation*}"}, "ch05_convolution/01_impulse_representation.html#eq-4-2": {"tex": "\\begin{equation*}\nx[n] = \\sum_{k=-\\infty}^{\\infty} x[k]\\,\\delta[n-k]. \\tag{4.2}\n\\end{equation*}"}, "ch05_convolution/01_impulse_representation.html#eq-4-3": {"tex": "\\begin{equation*}\n\\hat{x}(t) = \\sum_{k=-\\infty}^{\\infty} x(k\\Delta)\\,\\delta_\\Delta(t - k\\Delta)\\,\\Delta. \\tag{4.3}\n\\end{equation*}"}, "ch05_convolution/01_impulse_representation.html#eq-4-4": {"tex": "\\begin{equation*}\nx(t) = \\int_{-\\infty}^{\\infty} x(\\tau)\\,\\delta(t - \\tau)\\,d\\tau. \\tag{4.4}\n\\end{equation*}"}, "ch05_convolution/01_impulse_representation.html#eq-4-5": {"tex": "\\begin{equation*}\nh[n] = T\\{\\delta[n]\\}, \\qquad h(t) = T\\{\\delta(t)\\}. \\tag{4.5}\n\\end{equation*}"}, "ch05_convolution/01_impulse_representation.html#eq-4-6": {"tex": "\\begin{equation*}\ny[n] = \\sum_{k=-\\infty}^{\\infty} x[k]\\,h[n-k]. \\tag{4.6}\n\\end{equation*}"}, "ch05_convolution/01_impulse_representation.html#eq-4-7": {"tex": "\\begin{equation*}\ny(t) = \\int_{-\\infty}^{\\infty} x(\\tau)\\,h(t - \\tau)\\,d\\tau. \\tag{4.7}\n\\end{equation*}"}, "ch05_convolution/01_impulse_representation.html#eq-4-8": {"tex": "\\begin{equation*}\nu[n] = \\sum_{k=0}^{\\infty} \\delta[n-k]. \\tag{4.8}\n\\end{equation*}"}, "ch05_convolution/01_impulse_representation.html#eq-4-9": {"tex": "\\begin{equation*}\ns[n] = \\sum_{m=-\\infty}^{n} h[m]. \\tag{4.9}\n\\end{equation*}"}, "ch05_convolution/01_impulse_representation.html#eq-4-10": {"tex": "\\begin{equation*}\nh[n] = s[n] - s[n-1]. \\tag{4.10}\n\\end{equation*}"}, "ch05_convolution/01_impulse_representation.html#eq-4-11": {"tex": "\\begin{equation*}\ns(t) = \\int_{-\\infty}^{t} h(\\tau)\\,d\\tau, \\qquad h(t) = \\frac{ds(t)}{dt}. \\tag{4.11}\n\\end{equation*}"}, "ch05_convolution/01_impulse_representation.html#eq-4-12": {"tex": "\\begin{equation*}\nh[n] = (1-\\alpha)\\,\\alpha^{n}\\,u[n]. \\tag{4.12}\n\\end{equation*}"}, "ch05_convolution/01_impulse_representation.html#eq-4-13": {"tex": "\\begin{equation*}\nh(t) = \\frac{ds}{dt} = \\delta(t) - \\frac{1}{\\tau}\\,e^{-t/\\tau}\\,u(t). \\tag{4.13}\n\\end{equation*}"}, "ch05_convolution/01_impulse_representation.html#sec-4-1-1": {"tex": "\\delta[n] = \\begin{cases} 1, & n = 0, \\\\ 0, & n \\neq 0. \\end{cases}"}, "ch05_convolution/01_impulse_representation.html#sec-4-1-2": {"tex": "\\delta_\\Delta(t) = \\begin{cases} 1/\\Delta, & 0 \\le t < \\Delta, \\\\ 0, & \\text{otherwise.} \\end{cases}"}, "ch05_convolution/01_impulse_representation.html#sec-4-1-3": {"tex": "\\begin{equation*}\nh[n] = T\\{\\delta[n]\\}, \\qquad h(t) = T\\{\\delta(t)\\}. \\tag{4.5}\n\\end{equation*}"}, "ch05_convolution/01_impulse_representation.html#sec-4-1-4": {"tex": "y[n] = T\\{x[n]\\} = T\\Big\\{\\sum_{k} x[k]\\,\\delta[n-k]\\Big\\}."}, "ch05_convolution/01_impulse_representation.html#sec-4-1-5": {"tex": "\\begin{equation*}\nu[n] = \\sum_{k=0}^{\\infty} \\delta[n-k]. \\tag{4.8}\n\\end{equation*}"}, "ch05_convolution/01_impulse_representation.html#sec-4-1-6": {"tex": "y[n] = \\frac{1}{M}\\sum_{k=0}^{M-1} x[n-k]."}, "ch05_convolution/01_impulse_representation.html#sec-4-1-7": {"tex": "s(t) = 1 - \\left(1 - e^{-t/\\tau}\\right) = e^{-t/\\tau}\\,u(t)."}, "ch05_convolution/02_convolution_sum.html#eq-4-14": {"tex": "\\begin{equation*}\ny[n] = \\sum_{m=-\\infty}^{\\infty} h[m]\\,x[n-m]. \\tag{4.14}\n\\end{equation*}"}, "ch05_convolution/02_convolution_sum.html#eq-4-15": {"tex": "\\begin{equation*}\nL_y = N + M - 1 \\tag{4.15}\n\\end{equation*}"}, "ch05_convolution/02_convolution_sum.html#eq-4-16": {"tex": "\\begin{equation*}\nN \\cdot M \\ \\text{multiply-adds} \\tag{4.16}\n\\end{equation*}"}, "ch05_convolution/02_convolution_sum.html#eq-4-17": {"tex": "\\begin{equation*}\n\\sigma_y^2 = \\sigma^2 \\sum_{k} h[k]^2 = \\sigma^2 \\cdot M \\cdot \\frac{1}{M^2} = \\frac{\\sigma^2}{M}. \\tag{4.17}\n\\end{equation*}"}, "ch05_convolution/02_convolution_sum.html#sec-4-2": {"tex": "y[n] = \\sum_{k=-\\infty}^{\\infty} x[k]\\,h[n-k]"}, "ch05_convolution/02_convolution_sum.html#sec-4-2-1": {"tex": "y[n] = \\cdots + x[0]\\,h[n] + x[1]\\,h[n-1] + x[2]\\,h[n-2] + \\cdots"}, "ch05_convolution/02_convolution_sum.html#sec-4-2-3": {"tex": "\\begin{aligned}\ny[0] &= 3, \\\\\ny[1] &= 2 + 6 = 8, \\\\\ny[2] &= 1 + 4 + 9 = 14, \\\\\ny[3] &= 2 + 6 + 3 = 11, \\\\\ny[4] &= 3 + 2 = 5, \\\\\ny[5] &= 1 ,\n\\end{aligned}"}, "ch05_convolution/02_convolution_sum.html#sec-4-2-4": {"tex": "N_1 \\le k \\le N_1 + N - 1 \\qquad \\text{and} \\qquad M_1 \\le n - k \\le M_1 + M - 1 ."}, "ch05_convolution/02_convolution_sum.html#sec-4-2-5": {"tex": "\\begin{equation*}\nN \\cdot M \\ \\text{multiply-adds} \\tag{4.16}\n\\end{equation*}"}, "ch05_convolution/02_convolution_sum.html#sec-4-2-7": {"tex": "\\begin{equation*}\n\\sigma_y^2 = \\sigma^2 \\sum_{k} h[k]^2 = \\sigma^2 \\cdot M \\cdot \\frac{1}{M^2} = \\frac{\\sigma^2}{M}. \\tag{4.17}\n\\end{equation*}"}, "ch05_convolution/02_convolution_sum.html#sec-4-2-8": {"tex": "e[n] = \\sum_i \\text{MUAP}[n - n_i] = (d * \\text{MUAP})[n],"}, "ch20_eeg/03_event_related_activity.html#eq-13-10": {"tex": "\\begin{equation*}\nx_i(t) = s(t) + a(t)\\cos(\\omega_0 t + \\varphi_i) + v_i(t). \\tag{13.10}\n\\end{equation*}"}, "ch20_eeg/03_event_related_activity.html#eq-13-11": {"tex": "\\begin{equation*}\n\\mathbb{E}\\big[x_i(t)\\big] = s(t). \\tag{13.11}\n\\end{equation*}"}, "ch20_eeg/03_event_related_activity.html#eq-13-12": {"tex": "\\begin{equation*}\n\\mathbb{E}\\big[x_i^2(t)\\big] = s^2(t) + \\frac{a^2(t)}{2} + \\sigma^2 . \\tag{13.12}\n\\end{equation*}"}, "ch20_eeg/03_event_related_activity.html#eq-13-13": {"tex": "\\begin{equation*}\n\\hat\\sigma^2(t) = \\frac{1}{N-1}\\sum_{i=1}^{N}\\big(x_i(t) - \\bar{x}(t)\\big)^2, \\qquad\n\\widehat{\\mathrm{SE}}(t) = \\frac{\\hat\\sigma(t)}{\\sqrt{N}} . \\tag{13.13}\n\\end{equation*}"}, "ch20_eeg/03_event_related_activity.html#eq-13-14": {"tex": "\\begin{equation*}\n\\operatorname{Var}\\big[x_i^{\\text{bc}}(t)\\big] = \\sigma_w^2 + \\frac{\\sigma_w^2}{M} = \\sigma_w^2\\left(1 + \\frac{1}{M}\\right)\n\\quad\\text{instead of}\\quad \\sigma_d^2 + \\sigma_w^2 . \\tag{13.14}\n\\end{equation*}"}, "ch20_eeg/03_event_related_activity.html#eq-13-15": {"tex": "\\begin{equation*}\n\\mathrm{ERD}(t) = \\frac{P(t) - R}{R}\\times 100\\% . \\tag{13.15}\n\\end{equation*}"}, "ch20_eeg/03_event_related_activity.html#eq-13-16": {"tex": "\\begin{equation*}\nP_{\\text{ITV}}(t) = \\frac{1}{N-1}\\sum_{i=1}^{N}\\big(y_i(t) - \\bar{y}(t)\\big)^2 , \\tag{13.16}\n\\end{equation*}"}, "ch20_eeg/03_event_related_activity.html#sec-13-3-1": {"tex": "\\begin{equation*}\nx_i(t) = s(t) + a(t)\\cos(\\omega_0 t + \\varphi_i) + v_i(t). \\tag{13.10}\n\\end{equation*}"}, "ch20_eeg/03_event_related_activity.html#sec-13-3-2": {"tex": "\\begin{equation*}\n\\hat\\sigma^2(t) = \\frac{1}{N-1}\\sum_{i=1}^{N}\\big(x_i(t) - \\bar{x}(t)\\big)^2, \\qquad\n\\widehat{\\mathrm{SE}}(t) = \\frac{\\hat\\sigma(t)}{\\sqrt{N}} . \\tag{13.13}\n\\end{equation*}"}, "ch20_eeg/03_event_related_activity.html#sec-13-3-4": {"tex": "\\begin{equation*}\n\\mathrm{ERD}(t) = \\frac{P(t) - R}{R}\\times 100\\% . \\tag{13.15}\n\\end{equation*}"}, "ch20_eeg/02_eeg_spectral_analysis.html#eq-13-5": {"tex": "\\begin{equation*}\nP_{[f_1, f_2]} = \\int_{f_1}^{f_2} S_x(f)\\, df \\;\\approx\\; \\sum_{k:\\, f_1 \\le f_k \\le f_2} \\hat{S}_x(f_k)\\,\\Delta f , \\tag{13.5}\n\\end{equation*}"}, "ch20_eeg/02_eeg_spectral_analysis.html#eq-13-6": {"tex": "\\begin{equation*}\n\\begin{aligned}\n\\sum_k (u_k - \\bar u)\\big(y_k - \\bar y + \\beta (u_k - \\bar u)\\big) &= 0 \\\\\n\\hat\\beta &= -\\frac{\\sum_k (u_k - \\bar u)(y_k - \\bar y)}{\\sum_k (u_k - \\bar u)^2}, \\qquad \\hat c = \\bar y + \\hat\\beta \\bar u .\n\\end{aligned} \\tag{13.6}\n\\end{equation*}"}, "ch20_eeg/02_eeg_spectral_analysis.html#eq-13-7": {"tex": "\\begin{equation*}\n\\delta^{*} = -\\frac{b}{2a} = \\frac{y_- - y_+}{2\\,(y_- - 2y_0 + y_+)}, \\qquad \\hat f_{\\text{peak}} = f_{k_0} + \\delta^{*}\\Delta f . \\tag{13.7}\n\\end{equation*}"}, "ch20_eeg/02_eeg_spectral_analysis.html#eq-13-8": {"tex": "\\begin{equation*}\nH_{\\text{sp}} = -\\frac{1}{\\ln K}\\sum_{k=1}^{K} p_k \\ln p_k , \\qquad 0 \\le H_{\\text{sp}} \\le 1 . \\tag{13.8}\n\\end{equation*}"}, "ch20_eeg/02_eeg_spectral_analysis.html#eq-13-9": {"tex": "\\begin{equation*}\n\\text{Activity} = \\sigma_x^2, \\qquad\n\\text{Mobility} = \\sqrt{\\frac{\\sigma_{x'}^2}{\\sigma_x^2}}, \\qquad\n\\text{Complexity} = \\frac{\\text{Mobility}(x')}{\\text{Mobility}(x)} = \\sqrt{\\frac{\\sigma_{x''}^2\\,\\sigma_x^2}{\\left(\\sigma_{x'}^2\\right)^2}} . \\tag{13.9}\n\\end{equation*}"}, "ch20_eeg/02_eeg_spectral_analysis.html#sec-13-2-1": {"tex": "K = \\left\\lfloor \\frac{N - L}{D} \\right\\rfloor + 1"}, "ch20_eeg/02_eeg_spectral_analysis.html#sec-13-2-2": {"tex": "\\begin{equation*}\nP_{[f_1, f_2]} = \\int_{f_1}^{f_2} S_x(f)\\, df \\;\\approx\\; \\sum_{k:\\, f_1 \\le f_k \\le f_2} \\hat{S}_x(f_k)\\,\\Delta f , \\tag{13.5}\n\\end{equation*}"}, "ch20_eeg/02_eeg_spectral_analysis.html#sec-13-2-4": {"tex": "S(f) = \\frac{A}{f^{\\beta}} \\quad\\Longrightarrow\\quad \\log_{10} S(f) = \\log_{10} A - \\beta \\log_{10} f ,"}, "ch20_eeg/02_eeg_spectral_analysis.html#sec-13-2-5": {"tex": "\\int_{f_{\\text{lo}}}^{\\text{SEF}_q} S(f)\\, df = q \\int_{f_{\\text{lo}}}^{f_{\\text{hi}}} S(f)\\, df ."}, "ch20_eeg/02_eeg_spectral_analysis.html#sec-13-2-6": {"tex": "\\begin{equation*}\n\\text{Activity} = \\sigma_x^2, \\qquad\n\\text{Mobility} = \\sqrt{\\frac{\\sigma_{x'}^2}{\\sigma_x^2}}, \\qquad\n\\text{Complexity} = \\frac{\\text{Mobility}(x')}{\\text{Mobility}(x)} = \\sqrt{\\frac{\\sigma_{x''}^2\\,\\sigma_x^2}{\\left(\\sigma_{x'}^2\\right)^2}} . \\tag{13.9}\n\\end{equation*}"}, "ch20_eeg/01_eeg_fundamentals.html#eq-13-1": {"tex": "\\begin{equation*}\nA_{\\text{sync}} = N a, \\qquad A_{\\text{async}} = \\sqrt{N}\\,a, \\qquad \\frac{A_{\\text{sync}}}{A_{\\text{async}}} = \\sqrt{N}. \\tag{13.1}\n\\end{equation*}"}, "ch20_eeg/01_eeg_fundamentals.html#eq-13-2": {"tex": "\\begin{equation*}\n\\begin{aligned}\nv_i^{\\text{CAR}} &= v_i - \\frac{1}{M}\\sum_{k=1}^{M} v_k \\\\\n&= \\big(\\phi_i - \\phi_{\\text{ref}}\\big) - \\frac{1}{M}\\sum_{k=1}^{M}\\big(\\phi_k - \\phi_{\\text{ref}}\\big) \\\\\n&= \\phi_i - \\phi_{\\text{ref}} - \\bar{\\phi} + \\phi_{\\text{ref}} \\\\\n&= \\phi_i - \\bar{\\phi}, \\qquad \\bar{\\phi} = \\frac{1}{M}\\sum_{k=1}^{M}\\phi_k .\n\\end{aligned} \\tag{13.2}\n\\end{equation*}"}, "ch20_eeg/01_eeg_fundamentals.html#eq-13-3": {"tex": "\\begin{equation*}\nv_{i,j}^{\\text{bip}} = v_i - v_j = (\\phi_i - \\phi_{\\text{ref}}) - (\\phi_j - \\phi_{\\text{ref}}) = \\phi_i - \\phi_j, \\tag{13.3}\n\\end{equation*}"}, "ch20_eeg/01_eeg_fundamentals.html#eq-13-4": {"tex": "\\begin{equation*}\nL_i = v_i - \\frac{1}{4}\\sum_{k \\in \\mathcal{N}(i)} v_k . \\tag{13.4}\n\\end{equation*}"}, "ch20_eeg/01_eeg_fundamentals.html#sec-13-1-1": {"tex": "\\sum_{k=1}^{N} a\\cos(\\omega t + \\varphi_k) = \\operatorname{Re}\\left\\{a\\,e^{j\\omega t}\\sum_{k=1}^{N} e^{j\\varphi_k}\\right\\},"}, "ch20_eeg/01_eeg_fundamentals.html#sec-13-1-4": {"tex": "v_i(t) = \\phi_i(t) - \\phi_{\\text{ref}}(t),"}, "ch14_fir/01_linear_phase_fir.html#eq-9-1": {"tex": "\\begin{equation*}\ny[n] = \\sum_{k=0}^{M} b_k\\, x[n-k] = b_0\\,x[n] + b_1\\,x[n-1] + \\cdots + b_M\\,x[n-M]. \\tag{9.1}\n\\end{equation*}"}, "ch14_fir/01_linear_phase_fir.html#eq-9-2": {"tex": "\\begin{equation*}\nH(z) = \\sum_{n=0}^{M} h[n]\\, z^{-n} = \\frac{h[0]\\,z^{M} + h[1]\\,z^{M-1} + \\cdots + h[M]}{z^{M}}. \\tag{9.2}\n\\end{equation*}"}, "ch14_fir/01_linear_phase_fir.html#eq-9-3": {"tex": "\\begin{equation*}\nH(e^{j\\Omega}) = \\sum_{n=0}^{M} h[n]\\, e^{-j\\Omega n}. \\tag{9.3}\n\\end{equation*}"}, "ch14_fir/01_linear_phase_fir.html#eq-9-4": {"tex": "\\begin{equation*}\nH(e^{j\\Omega}) = A(\\Omega)\\, e^{-j\\alpha\\Omega}, \\tag{9.4}\n\\end{equation*}"}, "ch14_fir/01_linear_phase_fir.html#eq-9-5": {"tex": "\\begin{equation*}\nh[n] = h[M - n], \\qquad n = 0, 1, \\ldots, M. \\tag{9.5}\n\\end{equation*}"}, "ch14_fir/01_linear_phase_fir.html#eq-9-6": {"tex": "\\begin{equation*}\nH(e^{j\\Omega}) = e^{-j\\Omega M/2} A(\\Omega), \\qquad A(\\Omega) = h[M/2] + 2\\sum_{k=1}^{M/2} h[M/2 - k]\\cos(k\\Omega). \\tag{9.6}\n\\end{equation*}"}, "ch14_fir/01_linear_phase_fir.html#eq-9-7": {"tex": "\\begin{equation*}\nH(z) = \\pm\\, z^{-M} H(z^{-1}). \\tag{9.7}\n\\end{equation*}"}, "ch14_fir/01_linear_phase_fir.html#eq-9-8": {"tex": "\\begin{equation*}\n\\tau_g = -\\frac{d}{d\\Omega}\\left(\\beta - \\frac{\\Omega M}{2}\\right) = \\frac{M}{2}\\ \\text{samples} = \\frac{M}{2 f_s}\\ \\text{seconds}. \\tag{9.8}\n\\end{equation*}"}, "ch14_fir/01_linear_phase_fir.html#eq-9-9": {"tex": "\\begin{equation*}\ny[n] = h[M/2]\\,x[n - M/2] + \\sum_{k=0}^{M/2-1} h[k]\\,\\big(x[n-k] + x[n-M+k]\\big). \\tag{9.9}\n\\end{equation*}"}, "ch14_fir/01_linear_phase_fir.html#sec-9-1-1": {"tex": "\\begin{equation*}\ny[n] = \\sum_{k=0}^{M} b_k\\, x[n-k] = b_0\\,x[n] + b_1\\,x[n-1] + \\cdots + b_M\\,x[n-M]. \\tag{9.1}\n\\end{equation*}"}, "ch14_fir/01_linear_phase_fir.html#sec-9-1-2": {"tex": "\\begin{equation*}\nH(e^{j\\Omega}) = A(\\Omega)\\, e^{-j\\alpha\\Omega}, \\tag{9.4}\n\\end{equation*}"}, "ch14_fir/01_linear_phase_fir.html#sec-9-1-3": {"tex": "\\begin{equation*}\nh[n] = h[M - n], \\qquad n = 0, 1, \\ldots, M. \\tag{9.5}\n\\end{equation*}"}, "ch14_fir/01_linear_phase_fir.html#sec-9-1-4": {"tex": "\\begin{aligned}\n\\text{Type I} &(M \\text{ even, symmetric}): & H &= e^{-j\\Omega M/2}\\Big[h[\\tfrac{M}{2}] + 2\\textstyle\\sum_{k=1}^{M/2} h[\\tfrac{M}{2}-k]\\cos(k\\Omega)\\Big], \\\\\n\\text{Type II} &(M \\text{ odd, symmetric}): & H &= e^{-j\\Omega M/2}\\; 2\\textstyle\\sum_{k=1}^{(M+1)/2} h[\\tfrac{M+1}{2}-k]\\cos\\!\\big((k-\\tfrac12)\\Omega\\big), \\\\\n\\text{Type III} &(M \\text{ even, antisymmetric}): & H &= j\\,e^{-j\\Omega M/2}\\; 2\\textstyle\\sum_{k=1}^{M/2} h[\\tfrac{M}{2}-k]\\sin(k\\Omega), \\\\\n\\text{Type IV} &(M \\text{ odd, antisymmetric}): & H &= j\\,e^{-j\\Omega M/2}\\; 2\\textstyle\\sum_{k=1}^{(M+1)/2} h[\\tfrac{M+1}{2}-k]\\sin\\!\\big((k-\\tfrac12)\\Omega\\big).\n\\end{aligned}"}, "ch14_fir/01_linear_phase_fir.html#sec-9-1-5": {"tex": "H(1/z_0) = \\pm\\, z_0^{M}\\, H(z_0) = 0,"}, "ch14_fir/01_linear_phase_fir.html#sec-9-1-6": {"tex": "\\begin{equation*}\n\\tau_g = -\\frac{d}{d\\Omega}\\left(\\beta - \\frac{\\Omega M}{2}\\right) = \\frac{M}{2}\\ \\text{samples} = \\frac{M}{2 f_s}\\ \\text{seconds}. \\tag{9.8}\n\\end{equation*}"}, "ch01_introduction/03_acquisition_chain.html#eq-1-13": {"tex": "\\begin{equation*}\ni(G) = i_\\text{max}\\,\\frac{G}{K_m + G}, \\tag{1.13}\n\\end{equation*}"}, "ch01_introduction/03_acquisition_chain.html#eq-1-14": {"tex": "\\begin{equation*}\nZ_e(\\omega) = R_s + \\frac{R_d}{1 + j\\omega\\tau}. \\tag{1.14}\n\\end{equation*}"}, "ch01_introduction/03_acquisition_chain.html#eq-1-15": {"tex": "\\begin{equation*}\nZ_e(\\omega) = R_s + \\frac{R_d(1 - j\\omega\\tau)}{1 + \\omega^2\\tau^2}\n= \\underbrace{R_s + \\frac{R_d}{1 + \\omega^2\\tau^2}}_{\\operatorname{Re}\\{Z_e\\}}\n\\;-\\; j\\,\\underbrace{\\frac{\\omega\\tau R_d}{1 + \\omega^2\\tau^2}}_{-\\operatorname{Im}\\{Z_e\\}}. \\tag{1.15}\n\\end{equation*}"}, "ch01_introduction/03_acquisition_chain.html#eq-1-16": {"tex": "\\begin{equation*}\n\\frac{v_\\text{measured}}{v_\\text{ECG}} = \\frac{Z_\\text{in}}{Z_\\text{in} + Z_{e1} + Z_{e2}} \\tag{1.16}\n\\end{equation*}"}, "ch01_introduction/03_acquisition_chain.html#eq-1-17": {"tex": "\\begin{equation*}\nv_o = A_d\\, v_d + A_{cm}\\, v_{cm}, \\qquad A_d = \\frac{A_1 + A_2}{2}, \\quad A_{cm} = A_1 - A_2 . \\tag{1.17}\n\\end{equation*}"}, "ch01_introduction/03_acquisition_chain.html#eq-1-18": {"tex": "\\begin{equation*}\n\\text{CMRR} = \\left|\\frac{A_d}{A_{cm}}\\right|, \\qquad \\text{CMRR}_\\text{dB} = 20\\log_{10}\\left|\\frac{A_d}{A_{cm}}\\right|. \\tag{1.18}\n\\end{equation*}"}, "ch01_introduction/03_acquisition_chain.html#eq-1-19": {"tex": "\\begin{equation*}\nv_{a} - v_{b} = \\frac{v_d}{R_G}\\,(R_1 + R_G + R_1) = \\left(1 + \\frac{2R_1}{R_G}\\right) v_d . \\tag{1.19}\n\\end{equation*}"}, "ch01_introduction/03_acquisition_chain.html#eq-1-20": {"tex": "\\begin{equation*}\nv_+ - v_- = v_{cm}\\,\\frac{Z_{cm}\\,(Z_{e2} - Z_{e1})}{(Z_{cm} + Z_{e1})(Z_{cm} + Z_{e2})}\n\\;\\approx\\; v_{cm}\\,\\frac{Z_{e2} - Z_{e1}}{Z_{cm}}, \\tag{1.20}\n\\end{equation*}"}, "ch01_introduction/03_acquisition_chain.html#eq-1-21": {"tex": "\\begin{equation*}\nL = 10\\log_{10}\\frac{v_2^2/R}{v_1^2/R} = 10\\log_{10}\\left(\\frac{v_2}{v_1}\\right)^2 = 20\\log_{10}\\frac{v_2}{v_1}\\ \\text{dB}. \\tag{1.21}\n\\end{equation*}"}, "ch01_introduction/03_acquisition_chain.html#eq-1-22": {"tex": "\\begin{equation*}\n\\text{DR} = 20\\log_{10}\\frac{\\text{FSR}}{q} = 20\\log_{10} 2^N = N \\cdot 20\\log_{10}2 \\approx 6.02\\,N\\ \\text{dB}. \\tag{1.22}\n\\end{equation*}"}, "ch01_introduction/03_acquisition_chain.html#eq-1-23": {"tex": "\\begin{equation*}\nH(j\\omega) = \\frac{R}{R + \\dfrac{1}{j\\omega C}} = \\frac{j\\omega RC}{1 + j\\omega RC}, \\qquad\n|H(j\\omega)| = \\frac{\\omega\\tau}{\\sqrt{1 + \\omega^2\\tau^2}}, \\quad \\tau = RC, \\tag{1.23}\n\\end{equation*}"}, "ch01_introduction/03_acquisition_chain.html#sec-1-3-2": {"tex": "v = 5\\ \\tfrac{\\mu\\text{V}}{\\text{V}\\cdot\\text{mmHg}} \\times 5\\ \\text{V} \\times 120\\ \\text{mmHg} = 3.0\\ \\text{mV},"}, "ch01_introduction/03_acquisition_chain.html#sec-1-3-3": {"tex": "\\text{Ag} + \\text{Cl}^- \\rightleftharpoons \\text{AgCl} + e^- ,"}, "ch01_introduction/03_acquisition_chain.html#sec-1-3-4": {"tex": "v_d = v_+ - v_-, \\qquad v_{cm} = \\frac{v_+ + v_-}{2},\n\\qquad\\text{so that}\\qquad v_\\pm = v_{cm} \\pm \\frac{v_d}{2}."}, "ch01_introduction/03_acquisition_chain.html#sec-1-3-5": {"tex": "L = 10\\log_{10}\\frac{P_2}{P_1}\\ \\text{dB}."}, "ch01_introduction/03_acquisition_chain.html#sec-1-3-6": {"tex": "\\begin{equation*}\nH(j\\omega) = \\frac{R}{R + \\dfrac{1}{j\\omega C}} = \\frac{j\\omega RC}{1 + j\\omega RC}, \\qquad\n|H(j\\omega)| = \\frac{\\omega\\tau}{\\sqrt{1 + \\omega^2\\tau^2}}, \\quad \\tau = RC, \\tag{1.23}\n\\end{equation*}"}, "ch01_introduction/02_bioelectric_origins.html#eq-1-1": {"tex": "\\begin{equation*}\nJ = -D\\left(\\frac{dc}{dx} + \\frac{zF}{RT}\\,c\\,\\frac{d\\varphi}{dx}\\right). \\tag{1.1}\n\\end{equation*}"}, "ch01_introduction/02_bioelectric_origins.html#eq-1-2": {"tex": "\\begin{equation*}\nE = \\frac{RT}{zF}\\,\\ln\\frac{c_o}{c_i}. \\tag{1.2}\n\\end{equation*}"}, "ch01_introduction/02_bioelectric_origins.html#eq-1-3": {"tex": "\\begin{equation*}\nJ = P\\,u\\,\\frac{c_i - c_o\\,e^{-u}}{1 - e^{-u}}. \\tag{1.3}\n\\end{equation*}"}, "ch01_introduction/02_bioelectric_origins.html#eq-1-4": {"tex": "\\begin{equation*}\nV_m = \\frac{RT}{F}\\,\\ln\\frac{P_K[K]_o + P_\\text{Na}[Na]_o + P_\\text{Cl}[Cl]_i}{P_K[K]_i + P_\\text{Na}[Na]_i + P_\\text{Cl}[Cl]_o}. \\tag{1.4}\n\\end{equation*}"}, "ch01_introduction/02_bioelectric_origins.html#eq-1-5": {"tex": "\\begin{equation*}\nC_m\\,\\frac{dV}{dt} = I_\\text{ext} - \\bar{g}_\\text{Na}\\,m^3 h\\,(V - E_\\text{Na}) - \\bar{g}_K\\,n^4\\,(V - E_K) - g_L\\,(V - E_L). \\tag{1.5}\n\\end{equation*}"}, "ch01_introduction/02_bioelectric_origins.html#eq-1-6": {"tex": "\\begin{equation*}\n\\frac{dx}{dt} = \\alpha_x(V)\\,(1 - x) - \\beta_x(V)\\,x, \\qquad x \\in \\{m, h, n\\}. \\tag{1.6}\n\\end{equation*}"}, "ch01_introduction/02_bioelectric_origins.html#eq-1-7": {"tex": "\\begin{equation*}\n\\frac{dx}{dt} = \\alpha_x - (\\alpha_x + \\beta_x)\\,x = \\frac{x_\\infty(V) - x}{\\tau_x(V)}, \\qquad\nx_\\infty = \\frac{\\alpha_x}{\\alpha_x + \\beta_x}, \\quad \\tau_x = \\frac{1}{\\alpha_x + \\beta_x}. \\tag{1.7}\n\\end{equation*}"}, "ch01_introduction/02_bioelectric_origins.html#eq-1-8": {"tex": "\\begin{equation*}\n\\varphi(r) = \\int_r^\\infty \\frac{I}{4\\pi\\sigma r'^2}\\,dr' = \\frac{I}{4\\pi\\sigma}\\left[-\\frac{1}{r'}\\right]_r^\\infty = \\frac{I}{4\\pi\\sigma r}. \\tag{1.8}\n\\end{equation*}"}, "ch01_introduction/02_bioelectric_origins.html#eq-1-9": {"tex": "\\begin{equation*}\n\\varphi \\approx \\frac{I\\,d\\cos\\theta}{4\\pi\\sigma r^2} = \\frac{\\mathbf{p}\\cdot\\mathbf{r}}{4\\pi\\sigma r^3}, \\tag{1.9}\n\\end{equation*}"}, "ch01_introduction/02_bioelectric_origins.html#eq-1-10": {"tex": "\\begin{equation*}\n\\varphi(x) = \\frac{p\\,h}{4\\pi\\sigma\\,(x^2 + h^2)^{3/2}}, \\qquad \\varphi_\\text{max} = \\varphi(0) = \\frac{p}{4\\pi\\sigma h^2}. \\tag{1.10}\n\\end{equation*}"}, "ch01_introduction/02_bioelectric_origins.html#eq-1-11": {"tex": "\\begin{equation*}\nv_L(t) = \\mathbf{L}\\cdot\\mathbf{p}(t), \\tag{1.11}\n\\end{equation*}"}, "ch01_introduction/02_bioelectric_origins.html#eq-1-12": {"tex": "\\begin{equation*}\nv_\\text{II}(t) = v_\\text{I}(t) + v_\\text{III}(t). \\tag{1.12}\n\\end{equation*}"}, "ch01_introduction/02_bioelectric_origins.html#sec-1-2-2": {"tex": "J_\\text{diff} = -D\\,\\frac{dc}{dx},"}, "ch01_introduction/02_bioelectric_origins.html#sec-1-2-3": {"tex": "\\frac{dc}{dx} - \\frac{u}{d}\\,c = -\\frac{J}{D}."}, "ch01_introduction/02_bioelectric_origins.html#sec-1-2-4": {"tex": "\\begin{equation*}\nC_m\\,\\frac{dV}{dt} = I_\\text{ext} - \\bar{g}_\\text{Na}\\,m^3 h\\,(V - E_\\text{Na}) - \\bar{g}_K\\,n^4\\,(V - E_K) - g_L\\,(V - E_L). \\tag{1.5}\n\\end{equation*}"}, "ch01_introduction/02_bioelectric_origins.html#sec-1-2-6": {"tex": "\\begin{equation*}\n\\varphi(r) = \\int_r^\\infty \\frac{I}{4\\pi\\sigma r'^2}\\,dr' = \\frac{I}{4\\pi\\sigma}\\left[-\\frac{1}{r'}\\right]_r^\\infty = \\frac{I}{4\\pi\\sigma r}. \\tag{1.8}\n\\end{equation*}"}, "ch01_introduction/02_bioelectric_origins.html#sec-1-2-7": {"tex": "\\begin{equation*}\nv_L(t) = \\mathbf{L}\\cdot\\mathbf{p}(t), \\tag{1.11}\n\\end{equation*}"}, "ch16_noise_removal/02_wiener_filter.html#eq-10-10": {"tex": "\\begin{equation*}\nJ(\\mathbf{w}) = \\mathbb{E}\\big[e^2[n]\\big], \\qquad e[n] = d[n] - \\mathbf{w}^\\mathsf{T}\\mathbf{x}[n]. \\tag{10.10}\n\\end{equation*}"}, "ch16_noise_removal/02_wiener_filter.html#eq-10-11": {"tex": "\\begin{equation*}\n\\begin{aligned}\nJ(\\mathbf{w}) &= \\mathbb{E}\\big[(d[n] - \\mathbf{w}^\\mathsf{T}\\mathbf{x}[n])^2\\big] \\\\\n&= \\mathbb{E}\\big[d^2[n]\\big] - 2\\,\\mathbf{w}^\\mathsf{T}\\,\\mathbb{E}\\big[d[n]\\,\\mathbf{x}[n]\\big] + \\mathbf{w}^\\mathsf{T}\\,\\mathbb{E}\\big[\\mathbf{x}[n]\\,\\mathbf{x}^\\mathsf{T}[n]\\big]\\,\\mathbf{w} \\\\\n&= \\sigma_d^2 - 2\\,\\mathbf{w}^\\mathsf{T}\\mathbf{p} + \\mathbf{w}^\\mathsf{T}\\mathbf{R}\\,\\mathbf{w}.\n\\end{aligned} \\tag{10.11}\n\\end{equation*}"}, "ch16_noise_removal/02_wiener_filter.html#eq-10-12": {"tex": "\\begin{equation*}\n\\mathbb{E}\\big[e_o[n]\\,x[n-k]\\big] = 0, \\qquad k = 0, 1, \\ldots, M-1, \\tag{10.12}\n\\end{equation*}"}, "ch16_noise_removal/02_wiener_filter.html#eq-10-13": {"tex": "\\begin{equation*}\n\\begin{bmatrix}\nR_x[0] & R_x[1] & \\cdots & R_x[M-1] \\\\\nR_x[1] & R_x[0] & \\cdots & R_x[M-2] \\\\\n\\vdots & \\vdots & \\ddots & \\vdots \\\\\nR_x[M-1] & R_x[M-2] & \\cdots & R_x[0]\n\\end{bmatrix}\n\\begin{bmatrix} w_0 \\\\ w_1 \\\\ \\vdots \\\\ w_{M-1}\\end{bmatrix}\n=\n\\begin{bmatrix} p_0 \\\\ p_1 \\\\ \\vdots \\\\ p_{M-1}\\end{bmatrix},\n\\qquad\\text{i.e.}\\qquad\n\\mathbf{R}\\,\\mathbf{w}_o = \\mathbf{p}. \\tag{10.13}\n\\end{equation*}"}, "ch16_noise_removal/02_wiener_filter.html#eq-10-14": {"tex": "\\begin{equation*}\nJ_{\\min} = \\sigma_d^2 - 2\\,\\mathbf{w}_o^\\mathsf{T}\\mathbf{p} + \\mathbf{w}_o^\\mathsf{T}\\mathbf{p} = \\sigma_d^2 - \\mathbf{p}^\\mathsf{T}\\mathbf{w}_o. \\tag{10.14}\n\\end{equation*}"}, "ch16_noise_removal/02_wiener_filter.html#eq-10-15": {"tex": "\\begin{equation*}\nJ(\\mathbf{w}) = J_{\\min} + (\\mathbf{w} - \\mathbf{w}_o)^\\mathsf{T}\\,\\mathbf{R}\\,(\\mathbf{w} - \\mathbf{w}_o). \\tag{10.15}\n\\end{equation*}"}, "ch16_noise_removal/02_wiener_filter.html#eq-10-16": {"tex": "\\begin{equation*}\n\\sum_{i=-\\infty}^{\\infty} h[i]\\,R_x[k-i] = R_{sx}[k], \\qquad -\\infty < k < \\infty, \\tag{10.16}\n\\end{equation*}"}, "ch16_noise_removal/02_wiener_filter.html#eq-10-17": {"tex": "\\begin{equation*}\nH(e^{j\\Omega})\\,S_x(\\Omega) = S_{sx}(\\Omega)\n\\quad\\Longrightarrow\\quad\nH(e^{j\\Omega}) = \\frac{S_{sx}(\\Omega)}{S_x(\\Omega)}. \\tag{10.17}\n\\end{equation*}"}, "ch16_noise_removal/02_wiener_filter.html#eq-10-18": {"tex": "\\begin{equation*}\nH(e^{j\\Omega}) = \\frac{S_s(\\Omega)}{S_s(\\Omega) + S_v(\\Omega)}. \\tag{10.18}\n\\end{equation*}"}, "ch16_noise_removal/02_wiener_filter.html#eq-10-19": {"tex": "\\begin{equation*}\nH(e^{j\\Omega}) = \\frac{\\xi(\\Omega)}{1 + \\xi(\\Omega)}. \\tag{10.19}\n\\end{equation*}"}, "ch16_noise_removal/02_wiener_filter.html#eq-10-20": {"tex": "\\begin{equation*}\n\\begin{aligned}\nJ_{\\min} &= \\mathbb{E}\\big[s^2[n]\\big] - \\sum_i h[i]\\,\\mathbb{E}\\big[x[n-i]\\,s[n]\\big]\n= R_s[0] - \\sum_i h[i]\\,R_{sx}[i] \\\\\n&= \\frac{1}{2\\pi}\\int_{-\\pi}^{\\pi} S_s(\\Omega)\\,d\\Omega - \\frac{1}{2\\pi}\\int_{-\\pi}^{\\pi} H(e^{j\\Omega})\\,S_s(\\Omega)\\,d\\Omega \\\\\n&= \\frac{1}{2\\pi}\\int_{-\\pi}^{\\pi} \\frac{S_s(\\Omega)\\,S_v(\\Omega)}{S_s(\\Omega) + S_v(\\Omega)}\\,d\\Omega.\n\\end{aligned} \\tag{10.20}\n\\end{equation*}"}, "ch16_noise_removal/02_wiener_filter.html#sec-10-2-1": {"tex": "x[n] = s[n] + v[n],"}, "ch16_noise_removal/02_wiener_filter.html#sec-10-2-2": {"tex": "\\frac{\\partial J}{\\partial w_k} = \\mathbb{E}\\!\\left[2\\,e[n]\\,\\frac{\\partial e[n]}{\\partial w_k}\\right] = -2\\,\\mathbb{E}\\big[e[n]\\,x[n-k]\\big]."}, "ch16_noise_removal/02_wiener_filter.html#sec-10-2-3": {"tex": "\\begin{equation*}\n\\sum_{i=-\\infty}^{\\infty} h[i]\\,R_x[k-i] = R_{sx}[k], \\qquad -\\infty < k < \\infty, \\tag{10.16}\n\\end{equation*}"}, "ch16_noise_removal/01_signal_averaging.html#eq-10-1": {"tex": "\\begin{equation*}\nx_i[n] = s[n] + v_i[n], \\qquad i = 1, \\ldots, N. \\tag{10.1}\n\\end{equation*}"}, "ch16_noise_removal/01_signal_averaging.html#eq-10-2": {"tex": "\\begin{equation*}\n\\bar{x}_N[n] = \\frac{1}{N}\\sum_{i=1}^{N} x_i[n] = s[n] + \\underbrace{\\frac{1}{N}\\sum_{i=1}^{N} v_i[n]}_{\\bar{v}_N[n]}. \\tag{10.2}\n\\end{equation*}"}, "ch16_noise_removal/01_signal_averaging.html#eq-10-3": {"tex": "\\begin{equation*}\n\\operatorname{Var}\\big(\\bar{v}_N[n]\\big) = \\frac{1}{N^2}\\cdot N\\sigma^2 = \\frac{\\sigma^2}{N}. \\tag{10.3}\n\\end{equation*}"}, "ch16_noise_removal/01_signal_averaging.html#eq-10-4": {"tex": "\\begin{equation*}\n\\mathrm{SNR}_N = \\frac{P_s}{\\sigma^2/N} = N\\cdot\\mathrm{SNR}_1,\n\\qquad\n10\\log_{10}\\mathrm{SNR}_N = 10\\log_{10}\\mathrm{SNR}_1 + 10\\log_{10}N\\ \\text{dB}. \\tag{10.4}\n\\end{equation*}"}, "ch16_noise_removal/01_signal_averaging.html#eq-10-5": {"tex": "\\begin{equation*}\n\\operatorname{Var}\\big(\\bar{v}_N[n]\\big) = \\frac{N\\sigma^2 + N(N-1)\\rho\\sigma^2}{N^2} = \\frac{\\sigma^2}{N}\\big[1 + (N-1)\\rho\\big]. \\tag{10.5}\n\\end{equation*}"}, "ch16_noise_removal/01_signal_averaging.html#eq-10-6": {"tex": "\\begin{equation*}\n\\mathbb{E}\\big[\\bar{x}_N[n]\\big] = \\frac{1}{N}\\sum_{i=1}^{N}\\sum_{\\tau} p[\\tau]\\, s[n - \\tau] = \\sum_{\\tau} p[\\tau]\\, s[n - \\tau] = (p * s)[n]. \\tag{10.6}\n\\end{equation*}"}, "ch16_noise_removal/01_signal_averaging.html#eq-10-7": {"tex": "\\begin{equation*}\nP(f) = e^{-2\\pi^2\\sigma_\\tau^2 f^2}. \\tag{10.7}\n\\end{equation*}"}, "ch16_noise_removal/01_signal_averaging.html#eq-10-8": {"tex": "\\begin{equation*}\nf_c = \\frac{\\sqrt{\\ln 2}}{2\\pi\\,\\sigma_\\tau} \\approx \\frac{0.133}{\\sigma_\\tau}. \\tag{10.8}\n\\end{equation*}"}, "ch16_noise_removal/01_signal_averaging.html#eq-10-9": {"tex": "\\begin{equation*}\n\\operatorname{Var}\\big(\\operatorname{median}\\big) \\approx \\frac{2\\pi\\sigma^2}{4N} = \\frac{\\pi}{2}\\cdot\\frac{\\sigma^2}{N}. \\tag{10.9}\n\\end{equation*}"}, "ch16_noise_removal/01_signal_averaging.html#sec-10-1-1": {"tex": "\\begin{equation*}\nx_i[n] = s[n] + v_i[n], \\qquad i = 1, \\ldots, N. \\tag{10.1}\n\\end{equation*}"}, "ch16_noise_removal/01_signal_averaging.html#sec-10-1-2": {"tex": "\\mathbb{E}\\big[\\bar{x}_N[n]\\big] = s[n] + \\frac{1}{N}\\sum_{i=1}^{N}\\mathbb{E}\\big[v_i[n]\\big] = s[n]."}, "ch16_noise_removal/01_signal_averaging.html#sec-10-1-4": {"tex": "x_i[n] = s[n - \\tau_i] + v_i[n],"}, "ch16_noise_removal/01_signal_averaging.html#sec-10-1-7": {"tex": "\\begin{equation*}\n\\operatorname{Var}\\big(\\operatorname{median}\\big) \\approx \\frac{2\\pi\\sigma^2}{4N} = \\frac{\\pi}{2}\\cdot\\frac{\\sigma^2}{N}. \\tag{10.9}\n\\end{equation*}"}, "ch17_ecg/02_recording_the_ecg.html#eq-11-13": {"tex": "\\begin{equation*}\nZ_e(f) = R_s + \\frac{R_d}{1 + j2\\pi f R_d C_d}. \\tag{11.13}\n\\end{equation*}"}, "ch17_ecg/02_recording_the_ecg.html#eq-11-14": {"tex": "\\begin{equation*}\nv_{\\text{out}} = v_1\\,\\frac{R_3'}{R_2' + R_3'}\\left(1 + \\frac{R_3}{R_2}\\right) - v_2\\,\\frac{R_3}{R_2}. \\tag{11.14}\n\\end{equation*}"}, "ch17_ecg/02_recording_the_ecg.html#eq-11-15": {"tex": "\\begin{equation*}\nv_{d,\\text{error}} \\approx v_c\\,\\frac{Z_{e2} - Z_{e1}}{Z_{cm}}. \\tag{11.15}\n\\end{equation*}"}, "ch17_ecg/02_recording_the_ecg.html#eq-11-16": {"tex": "\\begin{equation*}\n\\big[y(t_2) - y(t_1)\\big] - \\big[x(t_2) - x(t_1)\\big] = -\\frac{1}{\\tau}\\int_{t_1}^{t_2} y(s)\\,ds . \\tag{11.16}\n\\end{equation*}"}, "ch17_ecg/02_recording_the_ecg.html#eq-11-17": {"tex": "\\begin{equation*}\n\\Delta_{\\text{ST}} \\approx -\\frac{A_{\\text{QRS}}}{\\tau} = -2\\pi f_c\\,A_{\\text{QRS}}. \\tag{11.17}\n\\end{equation*}"}, "ch17_ecg/02_recording_the_ecg.html#eq-11-18": {"tex": "\\begin{equation*}\nf_{\\text{alias}} = \\left|\\,f - k f_s\\,\\right|, \\qquad k = \\operatorname{round}(f / f_s), \\tag{11.18}\n\\end{equation*}"}, "ch17_ecg/02_recording_the_ecg.html#eq-11-19": {"tex": "\\begin{equation*}\n\\sigma_t^2 = \\frac{1}{T_s}\\int_{-T_s/2}^{T_s/2} e^2\\,de = \\frac{1}{T_s}\\cdot\\frac{2}{3}\\left(\\frac{T_s}{2}\\right)^3 = \\frac{T_s^2}{12},\n\\qquad \\sigma_t = \\frac{T_s}{\\sqrt{12}}. \\tag{11.19}\n\\end{equation*}"}, "ch17_ecg/02_recording_the_ecg.html#eq-11-20": {"tex": "\\begin{equation*}\n\\delta^* = -\\frac{b}{2a} = \\frac{y_{-1} - y_1}{2\\,(y_{-1} - 2y_0 + y_1)}, \\qquad\ny^* = y_0 - \\frac{(y_{-1} - y_1)\\,\\delta^*}{4}, \\tag{11.20}\n\\end{equation*}"}, "ch17_ecg/02_recording_the_ecg.html#sec-11-2-2": {"tex": "\\mathrm{Ag} + \\mathrm{Cl}^- \\;\\rightleftharpoons\\; \\mathrm{AgCl} + e^-"}, "ch17_ecg/02_recording_the_ecg.html#sec-11-2-3": {"tex": "V(s) = \\Phi\\!\\left(+\\tfrac{s}{2}\\right) - \\Phi\\!\\left(-\\tfrac{s}{2}\\right)\n= \\frac{2\\,p\\,(s/2)}{4\\pi\\sigma\\left[(s/2)^2 + d^2\\right]^{3/2}}\n\\;\\approx\\; \\frac{p\\,s}{4\\pi\\sigma\\,d^3} \\quad (s \\ll d)."}, "ch17_ecg/02_recording_the_ecg.html#sec-11-2-4": {"tex": "v_d = v_a - v_b, \\qquad v_c = \\frac{v_a + v_b}{2}, \\qquad v_{\\text{out}} = A_d\\,v_d + A_c\\,v_c,"}, "ch17_ecg/02_recording_the_ecg.html#sec-11-2-5": {"tex": "H(s) = \\frac{s\\tau}{1 + s\\tau}, \\qquad\n|H(f)| = \\frac{2\\pi f\\tau}{\\sqrt{1 + (2\\pi f\\tau)^2}}, \\qquad\n\\angle H(f) = 90^\\circ - \\arctan(2\\pi f \\tau),"}, "ch17_ecg/02_recording_the_ecg.html#sec-11-2-6": {"tex": "\\begin{equation*}\nf_{\\text{alias}} = \\left|\\,f - k f_s\\,\\right|, \\qquad k = \\operatorname{round}(f / f_s), \\tag{11.18}\n\\end{equation*}"}, "ch17_ecg/02_recording_the_ecg.html#sec-11-2-7": {"tex": "\\begin{equation*}\n\\sigma_t^2 = \\frac{1}{T_s}\\int_{-T_s/2}^{T_s/2} e^2\\,de = \\frac{1}{T_s}\\cdot\\frac{2}{3}\\left(\\frac{T_s}{2}\\right)^3 = \\frac{T_s^2}{12},\n\\qquad \\sigma_t = \\frac{T_s}{\\sqrt{12}}. \\tag{11.19}\n\\end{equation*}"}, "ch17_ecg/01_cardiac_electrophysiology.html#eq-11-1": {"tex": "\\begin{equation*}\n\\begin{aligned}\n\\Phi(\\mathbf{r}) &\\approx \\frac{I}{4\\pi\\sigma}\\left(\\frac{\\mathbf{d}\\cdot\\mathbf{R}}{2|\\mathbf{R}|^3} + \\frac{\\mathbf{d}\\cdot\\mathbf{R}}{2|\\mathbf{R}|^3}\\right) \\\\\n&= \\frac{\\mathbf{p}\\cdot\\mathbf{R}}{4\\pi\\sigma\\,|\\mathbf{R}|^3}, \\qquad \\mathbf{p} = I\\,\\mathbf{d}.\n\\end{aligned} \\tag{11.1}\n\\end{equation*}"}, "ch17_ecg/01_cardiac_electrophysiology.html#eq-11-2": {"tex": "\\begin{equation*}\n\\begin{aligned}\nV_{AB}(t) &= \\Phi(\\mathbf{r}_A, t) - \\Phi(\\mathbf{r}_B, t) \\\\\n&= \\mathbf{p}(t)\\cdot\\frac{\\mathbf{r}_A - \\mathbf{r}_0}{4\\pi\\sigma|\\mathbf{r}_A - \\mathbf{r}_0|^3} - \\mathbf{p}(t)\\cdot\\frac{\\mathbf{r}_B - \\mathbf{r}_0}{4\\pi\\sigma|\\mathbf{r}_B - \\mathbf{r}_0|^3} \\\\\n&= \\mathbf{p}(t)\\cdot\\mathbf{l}_{AB}.\n\\end{aligned} \\tag{11.2}\n\\end{equation*}"}, "ch17_ecg/01_cardiac_electrophysiology.html#eq-11-3": {"tex": "\\begin{equation*}\n\\text{I} = \\Phi_L - \\Phi_R, \\qquad \\text{II} = \\Phi_F - \\Phi_R, \\qquad \\text{III} = \\Phi_F - \\Phi_L. \\tag{11.3}\n\\end{equation*}"}, "ch17_ecg/01_cardiac_electrophysiology.html#eq-11-4": {"tex": "\\begin{equation*}\n\\begin{aligned}\n\\text{I} + \\text{III} &= (\\Phi_L - \\Phi_R) + (\\Phi_F - \\Phi_L) \\\\\n&= \\Phi_F - \\Phi_R = \\text{II}.\n\\end{aligned} \\tag{11.4}\n\\end{equation*}"}, "ch17_ecg/01_cardiac_electrophysiology.html#eq-11-5": {"tex": "\\begin{equation*}\n\\text{I} = |\\mathbf{p}|\\cos\\theta, \\qquad \\text{II} = |\\mathbf{p}|\\cos(\\theta - 60^\\circ), \\qquad \\text{III} = |\\mathbf{p}|\\cos(\\theta - 120^\\circ). \\tag{11.5}\n\\end{equation*}"}, "ch17_ecg/01_cardiac_electrophysiology.html#eq-11-6": {"tex": "\\begin{equation*}\n\\frac{\\Phi_R - \\Phi_{W}}{R_W} + \\frac{\\Phi_L - \\Phi_{W}}{R_W} + \\frac{\\Phi_F - \\Phi_{W}}{R_W} = 0\n\\quad\\Longrightarrow\\quad \\Phi_{W} = \\frac{\\Phi_R + \\Phi_L + \\Phi_F}{3}. \\tag{11.6}\n\\end{equation*}"}, "ch17_ecg/01_cardiac_electrophysiology.html#eq-11-7": {"tex": "\\begin{equation*}\n\\text{aVR} = \\Phi_R - \\frac{\\Phi_L + \\Phi_F}{2} = \\frac{2\\Phi_R - \\Phi_L - \\Phi_F}{2} = \\frac{3}{2}\\,V_R. \\tag{11.7}\n\\end{equation*}"}, "ch17_ecg/01_cardiac_electrophysiology.html#eq-11-8": {"tex": "\\begin{equation*}\n\\text{aVR} = -\\frac{\\text{I} + \\text{II}}{2}, \\qquad\n\\text{aVL} = \\text{I} - \\frac{\\text{II}}{2} = \\frac{\\text{I} - \\text{III}}{2}, \\qquad\n\\text{aVF} = \\text{II} - \\frac{\\text{I}}{2} = \\frac{\\text{II} + \\text{III}}{2}. \\tag{11.8}\n\\end{equation*}"}, "ch17_ecg/01_cardiac_electrophysiology.html#eq-11-9": {"tex": "\\begin{equation*}\n\\mathrm{HR} = \\frac{60}{\\mathrm{RR}} \\quad \\text{(beats per minute)}. \\tag{11.9}\n\\end{equation*}"}, "ch17_ecg/01_cardiac_electrophysiology.html#eq-11-10": {"tex": "\\begin{equation*}\n\\mathrm{QT} \\approx \\mathrm{QTc}\\,\\sqrt{\\mathrm{RR}/(1\\ \\text{s})}\n\\quad\\Longrightarrow\\quad\n\\mathrm{QTc}_{\\text{B}} = \\frac{\\mathrm{QT}}{\\sqrt{\\mathrm{RR}/(1\\ \\text{s})}}. \\tag{11.10}\n\\end{equation*}"}, "ch17_ecg/01_cardiac_electrophysiology.html#eq-11-11": {"tex": "\\begin{equation*}\n\\text{I} = -2\\,\\text{aVR} - \\text{II}, \\qquad \\text{III} = \\text{II} - \\text{I} = 2\\,\\text{II} + 2\\,\\text{aVR}. \\tag{11.11}\n\\end{equation*}"}, "ch17_ecg/01_cardiac_electrophysiology.html#eq-11-12": {"tex": "\\begin{equation*}\n\\theta_{\\text{QRS}} = \\operatorname{atan2}\\!\\left(\\frac{2}{\\sqrt{3}}\\,A_{\\text{aVF}},\\; A_{\\text{I}}\\right), \\tag{11.12}\n\\end{equation*}"}, "ch17_ecg/01_cardiac_electrophysiology.html#sec-11-1-2": {"tex": "\\Phi(\\mathbf{r}) = \\frac{I}{4\\pi\\sigma\\,|\\mathbf{r} - \\mathbf{r}_s|},"}, "ch17_ecg/01_cardiac_electrophysiology.html#sec-11-1-3": {"tex": "\\begin{equation*}\n\\text{I} = \\Phi_L - \\Phi_R, \\qquad \\text{II} = \\Phi_F - \\Phi_R, \\qquad \\text{III} = \\Phi_F - \\Phi_L. \\tag{11.3}\n\\end{equation*}"}, "ch17_ecg/01_cardiac_electrophysiology.html#sec-11-1-5": {"tex": "\\begin{equation*}\n\\mathrm{HR} = \\frac{60}{\\mathrm{RR}} \\quad \\text{(beats per minute)}. \\tag{11.9}\n\\end{equation*}"}, "ch17_ecg/01_cardiac_electrophysiology.html#sec-11-1-6": {"tex": "\\begin{equation*}\n\\text{I} = -2\\,\\text{aVR} - \\text{II}, \\qquad \\text{III} = \\text{II} - \\text{I} = 2\\,\\text{II} + 2\\,\\text{aVR}. \\tag{11.11}\n\\end{equation*}"}, "ch17_ecg/03_ecg_data_in_python.html#eq-11-21": {"tex": "\\begin{equation*}\nx[n] = \\frac{d[n] - b}{G}, \\qquad b = \\text{baseline (adu)}, \\quad G = \\text{gain (adu/mV)}. \\tag{11.21}\n\\end{equation*}"}, "ch17_ecg/03_ecg_data_in_python.html#eq-11-22": {"tex": "\\begin{equation*}\n\\begin{aligned}\nd_0 &= B_0 + 256\\,(B_1 \\bmod 16), \\\\\nd_1 &= B_2 + 256\\,\\lfloor B_1 / 16 \\rfloor .\n\\end{aligned} \\tag{11.22}\n\\end{equation*}"}, "ch17_ecg/03_ecg_data_in_python.html#eq-11-23": {"tex": "\\begin{equation*}\nr = \\frac{10\\ \\text{mm/mV}}{25\\ \\text{mm/s}} = 0.4\\ \\text{s/mV}. \\tag{11.23}\n\\end{equation*}"}, "ch17_ecg/03_ecg_data_in_python.html#eq-11-24": {"tex": "\\begin{equation*}\n\\mathrm{HR} = \\frac{60}{0.04\\,n} = \\frac{1500}{n}\\ \\text{bpm}\n\\qquad\\text{or, with } m \\text{ large boxes,}\\qquad\n\\mathrm{HR} = \\frac{60}{0.2\\,m} = \\frac{300}{m}\\ \\text{bpm}. \\tag{11.24}\n\\end{equation*}"}, "ch17_ecg/03_ecg_data_in_python.html#eq-11-25": {"tex": "\\begin{equation*}\n\\mathbb{E}\\!\\left[\\frac{60}{\\mathrm{RR}}\\right] \\approx \\frac{60}{\\mu} + \\frac{1}{2}\\cdot\\frac{120}{\\mu^3}\\,\\sigma^2\n= \\frac{60}{\\mu}\\left(1 + \\frac{\\sigma^2}{\\mu^2}\\right). \\tag{11.25}\n\\end{equation*}"}, "ch17_ecg/03_ecg_data_in_python.html#sec-11-3-2": {"tex": "\\begin{equation*}\nx[n] = \\frac{d[n] - b}{G}, \\qquad b = \\text{baseline (adu)}, \\quad G = \\text{gain (adu/mV)}. \\tag{11.21}\n\\end{equation*}"}, "ch17_ecg/03_ecg_data_in_python.html#sec-11-3-5": {"tex": "\\text{small box} = \\frac{1\\ \\text{mm}}{25\\ \\text{mm/s}} = 0.04\\ \\text{s} = 40\\ \\text{ms}, \\qquad\n\\text{large box} = 5 \\times 40\\ \\text{ms} = 0.2\\ \\text{s}."}, "ch17_ecg/03_ecg_data_in_python.html#sec-11-3-6": {"tex": "g(r) \\approx g(\\mu) + g'(\\mu)\\,(r - \\mu) + \\tfrac{1}{2}\\,g''(\\mu)\\,(r - \\mu)^2,\n\\qquad g'(\\mu) = -\\frac{60}{\\mu^2}, \\quad g''(\\mu) = \\frac{120}{\\mu^3}."}, "ch09_sampling/01_sampling_theorem.html#eq-6-1": {"tex": "\\begin{equation*}\nx_s(t) = \\sum_{n=-\\infty}^{\\infty} x[n]\\,\\delta(t - nT_s). \\tag{6.1}\n\\end{equation*}"}, "ch09_sampling/01_sampling_theorem.html#eq-6-2": {"tex": "\\begin{equation*}\nP(f) = \\frac{1}{T_s}\\sum_{k=-\\infty}^{\\infty} \\delta(f - k f_s) = f_s \\sum_{k=-\\infty}^{\\infty} \\delta(f - k f_s). \\tag{6.2}\n\\end{equation*}"}, "ch09_sampling/01_sampling_theorem.html#eq-6-3": {"tex": "\\begin{equation*}\nX_s(f) = \\frac{1}{T_s}\\sum_{k=-\\infty}^{\\infty} X(f - k f_s). \\tag{6.3}\n\\end{equation*}"}, "ch09_sampling/01_sampling_theorem.html#eq-6-4": {"tex": "\\begin{equation*}\nX_s(f) = \\sum_{n=-\\infty}^{\\infty} x[n]\\,e^{-j2\\pi f n T_s}. \\tag{6.4}\n\\end{equation*}"}, "ch09_sampling/01_sampling_theorem.html#eq-6-5": {"tex": "\\begin{equation*}\nf_s - B > B \\quad\\Longleftrightarrow\\quad f_s > 2B. \\tag{6.5}\n\\end{equation*}"}, "ch09_sampling/01_sampling_theorem.html#sec-6-1-1": {"tex": "x[n] = x(nT_s), \\qquad n = \\ldots, -1, 0, 1, 2, \\ldots"}, "ch09_sampling/01_sampling_theorem.html#sec-6-1-2": {"tex": "p(t) = \\sum_{n=-\\infty}^{\\infty} \\delta(t - nT_s),"}, "ch09_sampling/01_sampling_theorem.html#sec-6-1-3": {"tex": "X(f) = \\int_{-\\infty}^{\\infty} x(t)\\,e^{-j2\\pi f t}\\,dt, \\qquad x(t) = \\int_{-\\infty}^{\\infty} X(f)\\,e^{j2\\pi f t}\\,df,"}, "ch09_sampling/01_sampling_theorem.html#sec-6-1-4": {"tex": "X_s(f) = (X * P)(f) = \\int_{-\\infty}^{\\infty} X(\\nu)\\,P(f - \\nu)\\,d\\nu ."}, "ch09_sampling/01_sampling_theorem.html#sec-6-1-5": {"tex": "\\begin{equation*}\nf_s - B > B \\quad\\Longleftrightarrow\\quad f_s > 2B. \\tag{6.5}\n\\end{equation*}"}, "ch09_sampling/02_aliasing.html#eq-6-6": {"tex": "\\begin{equation*}\n\\cos\\!\\big(2\\pi (f_0 + k f_s) n T_s + \\varphi\\big) = \\cos(2\\pi f_0 n T_s + \\varphi) = x[n]. \\tag{6.6}\n\\end{equation*}"}, "ch09_sampling/02_aliasing.html#eq-6-7": {"tex": "\\begin{equation*}\n\\begin{aligned}\n\\cos\\!\\big(2\\pi (k f_s - f_0) n T_s + \\varphi\\big) &= \\cos\\!\\big(2\\pi k n - 2\\pi f_0 n T_s + \\varphi\\big) \\\\\n&= \\cos\\!\\big(-(2\\pi f_0 n T_s - \\varphi)\\big) \\\\\n&= \\cos(2\\pi f_0 n T_s - \\varphi), \n\\end{aligned} \\tag{6.7}\n\\end{equation*}"}, "ch09_sampling/02_aliasing.html#eq-6-8": {"tex": "\\begin{equation*}\nf_a = \\left| f - f_s \\operatorname{round}\\!\\left(\\frac{f}{f_s}\\right) \\right|. \\tag{6.8}\n\\end{equation*}"}, "ch09_sampling/02_aliasing.html#eq-6-9": {"tex": "\\begin{equation*}\nf > f_s - f_p. \\tag{6.9}\n\\end{equation*}"}, "ch09_sampling/02_aliasing.html#eq-6-10": {"tex": "\\begin{equation*}\nN \\ge \\frac{\\log_{10}\\!\\left(10^{A_s/10} - 1\\right)}{2\\log_{10}\\!\\left(f_{\\text{stop}}/f_c\\right)}. \\tag{6.10}\n\\end{equation*}"}, "ch09_sampling/02_aliasing.html#sec-6-2-1": {"tex": "x[n] = \\cos(2\\pi f_0 n T_s + \\varphi) = \\cos\\!\\left(2\\pi \\frac{f_0}{f_s} n + \\varphi\\right)."}, "ch09_sampling/02_aliasing.html#sec-6-2-2": {"tex": "\\begin{equation*}\nf_a = \\left| f - f_s \\operatorname{round}\\!\\left(\\frac{f}{f_s}\\right) \\right|. \\tag{6.8}\n\\end{equation*}"}, "ch09_sampling/02_aliasing.html#sec-6-2-4": {"tex": "\\begin{equation*}\nf > f_s - f_p. \\tag{6.9}\n\\end{equation*}"}, "ch24_wavelets/02_wavelet_denoising.html#eq-14-11": {"tex": "\\begin{equation*}\n\\mathbf{w} = \\mathbf{W}\\mathbf{y} = \\underbrace{\\mathbf{W}\\mathbf{x}}_{\\boldsymbol{\\theta}} + \\underbrace{\\mathbf{W}\\mathbf{v}}_{\\mathbf{z}}. \\tag{14.11}\n\\end{equation*}"}, "ch24_wavelets/02_wavelet_denoising.html#eq-14-12": {"tex": "\\begin{equation*}\n\\eta_H(w; \\lambda) = \\begin{cases} w, & |w| > \\lambda, \\\\ 0, & |w| \\le \\lambda. \\end{cases} \\tag{14.12}\n\\end{equation*}"}, "ch24_wavelets/02_wavelet_denoising.html#eq-14-13": {"tex": "\\begin{equation*}\n\\eta_S(w; \\lambda) = \\operatorname{sgn}(w)\\,\\max\\big(|w| - \\lambda,\\ 0\\big) = \\begin{cases} w - \\lambda, & w > \\lambda, \\\\ 0, & |w| \\le \\lambda, \\\\ w + \\lambda, & w < -\\lambda. \\end{cases} \\tag{14.13}\n\\end{equation*}"}, "ch24_wavelets/02_wavelet_denoising.html#eq-14-14": {"tex": "\\begin{equation*}\n\\eta_S(w;\\lambda) = \\arg\\min_{\\theta}\\; f(\\theta), \\qquad f(\\theta) = \\tfrac12 (w - \\theta)^2 + \\lambda|\\theta| . \\tag{14.14}\n\\end{equation*}"}, "ch24_wavelets/02_wavelet_denoising.html#eq-14-15": {"tex": "\\begin{equation*}\n\\lambda_U = \\sigma\\sqrt{2\\ln N}, \\tag{14.15}\n\\end{equation*}"}, "ch24_wavelets/02_wavelet_denoising.html#eq-14-16": {"tex": "\\begin{equation*}\nP\\Big(\\max_{i} |z_i| > \\sigma\\sqrt{2\\ln N}\\Big) \\le \\frac{2}{\\sqrt{2\\pi}\\,\\sqrt{2\\ln N}} = \\frac{1}{\\sqrt{\\pi \\ln N}} \\;\\longrightarrow\\; 0 \\quad (N \\to \\infty). \\tag{14.16}\n\\end{equation*}"}, "ch24_wavelets/02_wavelet_denoising.html#eq-14-17": {"tex": "\\begin{equation*}\n\\hat\\sigma = \\frac{\\operatorname{median}\\big(|d_1[k]|\\big)}{0.6745}. \\tag{14.17}\n\\end{equation*}"}, "ch24_wavelets/02_wavelet_denoising.html#eq-14-18": {"tex": "\\begin{equation*}\n\\lambda_B = \\frac{\\sigma^2}{\\sigma_x} \\tag{14.18}\n\\end{equation*}"}, "ch24_wavelets/02_wavelet_denoising.html#eq-14-19": {"tex": "\\begin{equation*}\n\\text{SNR}_{\\text{out}} = 10\\log_{10}\\frac{\\sum_n x[n]^2}{\\sum_n \\big(\\hat x[n] - x[n]\\big)^2}, \\qquad\n\\text{PRD} = 100\\,\\sqrt{\\frac{\\sum_n \\big(\\hat x[n] - x[n]\\big)^2}{\\sum_n x[n]^2}}\\ \\%. \\tag{14.19}\n\\end{equation*}"}, "ch24_wavelets/02_wavelet_denoising.html#eq-14-20": {"tex": "\\begin{equation*}\n\\hat{x}_{\\text{TI}}[n] = \\frac{1}{S}\\sum_{s=0}^{S-1} \\Big(\\mathcal{D}\\big(y[\\,\\cdot + s\\,]\\big)\\Big)[n - s], \\tag{14.20}\n\\end{equation*}"}, "ch24_wavelets/02_wavelet_denoising.html#sec-14-2-1": {"tex": "y[n] = x[n] + v[n], \\qquad n = 0, 1, \\ldots, N-1,"}, "ch24_wavelets/02_wavelet_denoising.html#sec-14-2-2": {"tex": "\\begin{equation*}\n\\eta_H(w; \\lambda) = \\begin{cases} w, & |w| > \\lambda, \\\\ 0, & |w| \\le \\lambda. \\end{cases} \\tag{14.12}\n\\end{equation*}"}, "ch24_wavelets/02_wavelet_denoising.html#sec-14-2-3": {"tex": "\\begin{equation*}\n\\lambda_U = \\sigma\\sqrt{2\\ln N}, \\tag{14.15}\n\\end{equation*}"}, "ch24_wavelets/02_wavelet_denoising.html#sec-14-2-4": {"tex": "\\begin{equation*}\n\\hat\\sigma = \\frac{\\operatorname{median}\\big(|d_1[k]|\\big)}{0.6745}. \\tag{14.17}\n\\end{equation*}"}, "ch24_wavelets/02_wavelet_denoising.html#sec-14-2-5": {"tex": "\\begin{equation*}\n\\text{SNR}_{\\text{out}} = 10\\log_{10}\\frac{\\sum_n x[n]^2}{\\sum_n \\big(\\hat x[n] - x[n]\\big)^2}, \\qquad\n\\text{PRD} = 100\\,\\sqrt{\\frac{\\sum_n \\big(\\hat x[n] - x[n]\\big)^2}{\\sum_n x[n]^2}}\\ \\%. \\tag{14.19}\n\\end{equation*}"}, "ch24_wavelets/02_wavelet_denoising.html#sec-14-2-8": {"tex": "\\begin{equation*}\n\\hat{x}_{\\text{TI}}[n] = \\frac{1}{S}\\sum_{s=0}^{S-1} \\Big(\\mathcal{D}\\big(y[\\,\\cdot + s\\,]\\big)\\Big)[n - s], \\tag{14.20}\n\\end{equation*}"}, "ch24_wavelets/01_dwt_filter_banks.html#eq-14-1": {"tex": "\\begin{equation*}\nW_x(a, b) = \\int_{-\\infty}^{\\infty} x(t)\\, \\frac{1}{\\sqrt{a}}\\, \\psi^*\\!\\left(\\frac{t - b}{a}\\right) dt, \\qquad a > 0. \\tag{14.1}\n\\end{equation*}"}, "ch24_wavelets/01_dwt_filter_banks.html#eq-14-2": {"tex": "\\begin{equation*}\n\\frac{1}{\\sqrt{2^j}}\\,\\psi\\!\\left(\\frac{t - k 2^j}{2^j}\\right) = 2^{-j/2}\\,\\psi\\!\\left(2^{-j} t - k\\right) \\equiv \\psi_{j,k}(t), \\qquad j, k \\in \\mathbb{Z}. \\tag{14.2}\n\\end{equation*}"}, "ch24_wavelets/01_dwt_filter_banks.html#eq-14-3": {"tex": "\\begin{equation*}\na_1[k] = \\frac{x[2k] + x[2k+1]}{\\sqrt{2}}, \\qquad d_1[k] = \\frac{x[2k] - x[2k+1]}{\\sqrt{2}}. \\tag{14.3}\n\\end{equation*}"}, "ch24_wavelets/01_dwt_filter_banks.html#eq-14-4": {"tex": "\\begin{equation*}\nW(z) = \\tfrac12\\big[V(z) + V(-z)\\big]. \\tag{14.4}\n\\end{equation*}"}, "ch24_wavelets/01_dwt_filter_banks.html#eq-14-5": {"tex": "\\begin{equation*}\n\\hat{X}(z) = \\underbrace{\\tfrac12\\big[F_0(z)H_0(z) + F_1(z)H_1(z)\\big]}_{T(z)\\ \\text{(distortion)}}\\, X(z)\n\\;+\\; \\underbrace{\\tfrac12\\big[F_0(z)H_0(-z) + F_1(z)H_1(-z)\\big]}_{A(z)\\ \\text{(aliasing)}}\\, X(-z). \\tag{14.5}\n\\end{equation*}"}, "ch24_wavelets/01_dwt_filter_banks.html#eq-14-6": {"tex": "\\begin{equation*}\n\\begin{aligned}\n&\\text{alias cancellation:} && F_0(z)H_0(-z) + F_1(z)H_1(-z) = 0, \\\\\n&\\text{no distortion:} && F_0(z)H_0(z) + F_1(z)H_1(z) = 2z^{-\\ell}.\n\\end{aligned} \\tag{14.6}\n\\end{equation*}"}, "ch24_wavelets/01_dwt_filter_banks.html#eq-14-7": {"tex": "\\begin{equation*}\nh_1[n] = (-1)^{n+1}\\, h_0[L - 1 - n], \\qquad f_0[n] = h_0[L-1-n], \\qquad f_1[n] = h_1[L-1-n]. \\tag{14.7}\n\\end{equation*}"}, "ch24_wavelets/01_dwt_filter_banks.html#eq-14-8": {"tex": "\\begin{equation*}\n\\sum_n n^m\\, h_1[n] = 0, \\qquad m = 0, 1, \\ldots, p - 1. \\tag{14.8}\n\\end{equation*}"}, "ch24_wavelets/01_dwt_filter_banks.html#eq-14-9": {"tex": "\\begin{equation*}\nd_j \\;\\leftrightarrow\\; \\left[\\frac{f_s}{2^{j+1}},\\ \\frac{f_s}{2^{j}}\\right], \\qquad a_J \\;\\leftrightarrow\\; \\left[0,\\ \\frac{f_s}{2^{J+1}}\\right]. \\tag{14.9}\n\\end{equation*}"}, "ch24_wavelets/01_dwt_filter_banks.html#eq-14-10": {"tex": "\\begin{equation*}\nH^{(j)}_{\\text{eq}}(z) = H_1\\!\\left(z^{2^{j-1}}\\right) \\prod_{i=0}^{j-2} H_0\\!\\left(z^{2^i}\\right). \\tag{14.10}\n\\end{equation*}"}, "ch24_wavelets/01_dwt_filter_banks.html#sec-14-1-1": {"tex": "\\begin{equation*}\nW_x(a, b) = \\int_{-\\infty}^{\\infty} x(t)\\, \\frac{1}{\\sqrt{a}}\\, \\psi^*\\!\\left(\\frac{t - b}{a}\\right) dt, \\qquad a > 0. \\tag{14.1}\n\\end{equation*}"}, "ch24_wavelets/01_dwt_filter_banks.html#sec-14-1-2": {"tex": "\\text{averages} = [5,\\ 11,\\ 7,\\ 5], \\qquad \\text{half-differences} = [-1,\\ -1,\\ 1,\\ 0]."}, "ch24_wavelets/01_dwt_filter_banks.html#sec-14-1-3": {"tex": "w[n] = \\tfrac12\\big(1 + (-1)^n\\big)\\, v[n] ."}, "ch24_wavelets/01_dwt_filter_banks.html#sec-14-1-4": {"tex": "\\begin{equation*}\n\\sum_n n^m\\, h_1[n] = 0, \\qquad m = 0, 1, \\ldots, p - 1. \\tag{14.8}\n\\end{equation*}"}, "ch24_wavelets/01_dwt_filter_banks.html#sec-14-1-6": {"tex": "\\begin{equation*}\nd_j \\;\\leftrightarrow\\; \\left[\\frac{f_s}{2^{j+1}},\\ \\frac{f_s}{2^{j}}\\right], \\qquad a_J \\;\\leftrightarrow\\; \\left[0,\\ \\frac{f_s}{2^{J+1}}\\right]. \\tag{14.9}\n\\end{equation*}"}, "ch07_fourier_series/03_convergence_gibbs.html#eq-5-25": {"tex": "\\begin{equation*}\nx_K(t) = \\sum_{n=-K}^{K} c_n\\, e^{jn\\omega_0 t}, \\qquad c_n = \\frac{1}{T}\\int_T x(\\tau)\\,e^{-jn\\omega_0 \\tau}\\,d\\tau. \\tag{5.25}\n\\end{equation*}"}, "ch07_fourier_series/03_convergence_gibbs.html#eq-5-26": {"tex": "\\begin{equation*}\nx_K(t) = \\frac{1}{T}\\int_T x(\\tau)\\,D_K(t - \\tau)\\,d\\tau, \\qquad D_K(u) = \\sum_{n=-K}^{K} e^{jn\\omega_0 u}. \\tag{5.26}\n\\end{equation*}"}, "ch07_fourier_series/03_convergence_gibbs.html#eq-5-27": {"tex": "\\begin{equation*}\nD_K(u) = \\frac{\\sin\\!\\big((K + \\tfrac12)\\,\\omega_0 u\\big)}{\\sin(\\omega_0 u/2)}, \\qquad D_K(0) = 2K + 1. \\tag{5.27}\n\\end{equation*}"}, "ch07_fourier_series/03_convergence_gibbs.html#eq-5-28": {"tex": "\\begin{equation*}\n\\lim_{K\\to\\infty} x_K(t_0) = \\frac{x(t_0^-) + x(t_0^+)}{2}. \\tag{5.28}\n\\end{equation*}"}, "ch07_fourier_series/03_convergence_gibbs.html#eq-5-29": {"tex": "\\begin{equation*}\nE_K = \\sum_{|n| > K} |c_n|^2 . \\tag{5.29}\n\\end{equation*}"}, "ch07_fourier_series/03_convergence_gibbs.html#eq-5-30": {"tex": "\\begin{equation*}\n\\frac{1}{T}\\int_T |x(t) - p(t)|^2\\,dt = \\sum_{|n|\\le K} |c_n - d_n|^2 + \\sum_{|n|>K} |c_n|^2 \\;\\ge\\; E_K , \\tag{5.30}\n\\end{equation*}"}, "ch07_fourier_series/03_convergence_gibbs.html#eq-5-31": {"tex": "\\begin{equation*}\n\\lim_{M\\to\\infty} S_M(t_M) = \\frac{2}{\\pi}\\operatorname{Si}(\\pi) \\approx 1.17898 . \\tag{5.31}\n\\end{equation*}"}, "ch07_fourier_series/03_convergence_gibbs.html#eq-5-32": {"tex": "\\begin{equation*}\nc_n = \\underbrace{\\frac{1}{j2\\pi n}\\sum_i J_i\\,e^{-jn\\omega_0 t_i}}_{\\text{jumps of } x} \\;+\\; \\frac{1}{jn\\omega_0}\\,c_n[x'], \\qquad n \\neq 0, \\tag{5.32}\n\\end{equation*}"}, "ch07_fourier_series/03_convergence_gibbs.html#eq-5-33": {"tex": "\\begin{equation*}\n\\sigma_K(t) = \\sum_{n=-K}^{K}\\left(1 - \\frac{|n|}{K+1}\\right) c_n\\,e^{jn\\omega_0 t}. \\tag{5.33}\n\\end{equation*}"}, "ch07_fourier_series/03_convergence_gibbs.html#eq-5-34": {"tex": "\\begin{equation*}\n\\tilde{x}_K(t) = \\sum_{n=-K}^{K}\\operatorname{sinc}\\!\\left(\\frac{n}{K+1}\\right) c_n\\,e^{jn\\omega_0 t}, \\qquad \\operatorname{sinc}(v) = \\frac{\\sin(\\pi v)}{\\pi v}. \\tag{5.34}\n\\end{equation*}"}, "ch07_fourier_series/03_convergence_gibbs.html#sec-5-3-1": {"tex": "\\begin{equation*}\nx_K(t) = \\sum_{n=-K}^{K} c_n\\, e^{jn\\omega_0 t}, \\qquad c_n = \\frac{1}{T}\\int_T x(\\tau)\\,e^{-jn\\omega_0 \\tau}\\,d\\tau. \\tag{5.25}\n\\end{equation*}"}, "ch07_fourier_series/03_convergence_gibbs.html#sec-5-3-2": {"tex": "\\begin{aligned}\nx_K(t) &= \\sum_{n=-K}^{K}\\left[\\frac{1}{T}\\int_T x(\\tau)\\,e^{-jn\\omega_0\\tau}\\,d\\tau\\right] e^{jn\\omega_0 t} \\\\\n       &= \\frac{1}{T}\\int_T x(\\tau)\\left[\\sum_{n=-K}^{K} e^{jn\\omega_0 (t-\\tau)}\\right] d\\tau .\n\\end{aligned}"}, "ch07_fourier_series/03_convergence_gibbs.html#sec-5-3-3": {"tex": "E_K = \\frac{1}{T}\\int_T \\big|x(t) - x_K(t)\\big|^2\\,dt ."}, "ch07_fourier_series/03_convergence_gibbs.html#sec-5-3-4": {"tex": "S_M(t) = \\frac{4}{\\pi}\\sum_{k=1}^{M}\\frac{\\sin\\!\\big((2k-1)\\omega_0 t\\big)}{2k-1}."}, "ch07_fourier_series/03_convergence_gibbs.html#sec-5-3-5": {"tex": "\\int_{t_i}^{t_{i+1}} x(t)\\,e^{-jn\\omega_0 t}\\,dt = \\left[\\frac{x(t)\\,e^{-jn\\omega_0 t}}{-jn\\omega_0}\\right]_{t_i^+}^{t_{i+1}^-} + \\frac{1}{jn\\omega_0}\\int_{t_i}^{t_{i+1}} x'(t)\\,e^{-jn\\omega_0 t}\\,dt ."}, "ch07_fourier_series/03_convergence_gibbs.html#sec-5-3-6": {"tex": "\\sigma_K(t) = \\frac{1}{K+1}\\sum_{m=0}^{K} x_m(t)."}, "ch07_fourier_series/02_complex_fourier_series.html#eq-5-12": {"tex": "\\begin{equation*}\nc_0 = a_0, \\qquad c_n = \\frac{a_n - jb_n}{2}, \\qquad c_{-n} = \\frac{a_n + jb_n}{2}. \\tag{5.12}\n\\end{equation*}"}, "ch07_fourier_series/02_complex_fourier_series.html#eq-5-13": {"tex": "\\begin{equation*}\nx(t) = \\sum_{n=-\\infty}^{\\infty} c_n\\, e^{jn\\omega_0 t}. \\tag{5.13}\n\\end{equation*}"}, "ch07_fourier_series/02_complex_fourier_series.html#eq-5-14": {"tex": "\\begin{equation*}\nc_{-n} = c_n^* \\qquad \\text{for real } x(t). \\tag{5.14}\n\\end{equation*}"}, "ch07_fourier_series/02_complex_fourier_series.html#eq-5-15": {"tex": "\\begin{equation*}\nc_n = \\frac{1}{2}\\cdot\\frac{2}{T}\\int_T x(t)\\Big[\\cos(n\\omega_0 t) - j\\sin(n\\omega_0 t)\\Big]dt = \\frac{1}{T}\\int_T x(t)\\,e^{-jn\\omega_0 t}\\,dt, \\tag{5.15}\n\\end{equation*}"}, "ch07_fourier_series/02_complex_fourier_series.html#eq-5-16": {"tex": "\\begin{equation*}\nc_n = \\frac{A_n\\cos\\varphi_n + jA_n\\sin\\varphi_n}{2} = \\frac{A_n}{2}\\,e^{j\\varphi_n}, \\qquad |c_n| = \\frac{A_n}{2}, \\quad \\angle c_n = \\varphi_n \\quad (n \\ge 1). \\tag{5.16}\n\\end{equation*}"}, "ch07_fourier_series/02_complex_fourier_series.html#eq-5-17": {"tex": "\\begin{equation*}\n\\frac{1}{T}\\int_T e^{jm\\omega_0 t}\\,e^{-jn\\omega_0 t}\\,dt = \\begin{cases}1, & m = n,\\\\ 0, & m \\neq n.\\end{cases} \\tag{5.17}\n\\end{equation*}"}, "ch07_fourier_series/02_complex_fourier_series.html#eq-5-18": {"tex": "\\begin{equation*}\nd_n = \\frac{1}{T}\\int_T x(t - t_0)\\,e^{-jn\\omega_0 t}\\,dt = \\frac{1}{T}\\int_T x(u)\\,e^{-jn\\omega_0 (u + t_0)}\\,du = e^{-jn\\omega_0 t_0}\\,c_n. \\tag{5.18}\n\\end{equation*}"}, "ch07_fourier_series/02_complex_fourier_series.html#eq-5-19": {"tex": "\\begin{equation*}\nP = \\frac{1}{T}\\int_T |x(t)|^2\\,dt = \\sum_{n=-\\infty}^{\\infty} |c_n|^2. \\tag{5.19}\n\\end{equation*}"}, "ch07_fourier_series/02_complex_fourier_series.html#eq-5-20": {"tex": "\\begin{equation*}\nP = a_0^2 + \\sum_{n=1}^{\\infty}\\frac{A_n^2}{2}. \\tag{5.20}\n\\end{equation*}"}, "ch07_fourier_series/02_complex_fourier_series.html#eq-5-21": {"tex": "\\begin{equation*}\nc_n = \\frac{A\\tau}{T}\\cdot\\frac{\\sin(\\pi n\\tau/T)}{\\pi n\\tau/T} = \\frac{A\\tau}{T}\\,\\operatorname{sinc}\\!\\left(\\frac{n\\tau}{T}\\right) = A\\,d\\,\\operatorname{sinc}(n d), \\tag{5.21}\n\\end{equation*}"}, "ch07_fourier_series/02_complex_fourier_series.html#eq-5-22": {"tex": "\\begin{equation*}\n\\operatorname{sinc}(u) = \\frac{\\sin(\\pi u)}{\\pi u}, \\qquad \\operatorname{sinc}(0) = 1. \\tag{5.22}\n\\end{equation*}"}, "ch07_fourier_series/02_complex_fourier_series.html#eq-5-23": {"tex": "\\begin{equation*}\n\\hat{c}_k = \\frac{1}{N}\\sum_{n=0}^{N-1} x[n]\\,e^{-j2\\pi kn/N}. \\tag{5.23}\n\\end{equation*}"}, "ch07_fourier_series/02_complex_fourier_series.html#eq-5-24": {"tex": "\\begin{equation*}\n\\hat{c}_k = \\sum_{\\ell=-\\infty}^{\\infty} c_{k + \\ell N} = c_k + c_{k+N} + c_{k-N} + c_{k+2N} + \\cdots \\tag{5.24}\n\\end{equation*}"}, "ch07_fourier_series/02_complex_fourier_series.html#sec-5-2-1": {"tex": "x(t) = a_0 + \\sum_{n=1}^{\\infty}\\Big[a_n\\cos(n\\omega_0 t) + b_n\\sin(n\\omega_0 t)\\Big],"}, "ch07_fourier_series/02_complex_fourier_series.html#sec-5-2-2": {"tex": "\\langle x, y\\rangle = \\frac{1}{T}\\int_T x(t)\\,y^*(t)\\,dt,"}, "ch07_fourier_series/02_complex_fourier_series.html#sec-5-2-3": {"tex": "c_n^* = \\frac{1}{T}\\int_T x^*(t)\\,e^{+jn\\omega_0 t}\\,dt = \\frac{1}{T}\\int_T x(t)\\,e^{-j(-n)\\omega_0 t}\\,dt = c_{-n}."}, "ch07_fourier_series/02_complex_fourier_series.html#sec-5-2-4": {"tex": "|x(t)|^2 = \\left(\\sum_{m=-\\infty}^{\\infty} c_m e^{jm\\omega_0 t}\\right)\\left(\\sum_{n=-\\infty}^{\\infty} c_n^* e^{-jn\\omega_0 t}\\right) = \\sum_{m}\\sum_{n} c_m c_n^*\\, e^{j(m - n)\\omega_0 t}."}, "ch07_fourier_series/02_complex_fourier_series.html#sec-5-2-5": {"tex": "c_n = \\frac{1}{T}\\int_{-\\tau/2}^{\\tau/2} A\\,e^{-jn\\omega_0 t}\\,dt ."}, "ch07_fourier_series/02_complex_fourier_series.html#sec-5-2-6": {"tex": "c_k = \\frac{1}{T}\\int_0^T x(t)\\,e^{-jk\\omega_0 t}\\,dt \\approx \\frac{1}{T}\\sum_{n=0}^{N-1} x(t_n)\\,e^{-jk\\omega_0 t_n}\\,\\frac{T}{N}."}, "ch07_fourier_series/02_complex_fourier_series.html#sec-5-2-7": {"tex": "c_n = \\frac{\\tau}{T}\\operatorname{sinc}\\!\\left(\\frac{n\\tau}{T}\\right)e^{-jn\\omega_0\\tau/2} \\;+\\; a_r\\frac{\\tau_r}{T}\\operatorname{sinc}\\!\\left(\\frac{n\\tau_r}{T}\\right)e^{-jn\\omega_0(\\tau + \\tau_r/2)},"}, "ch07_fourier_series/01_fourier_series_derivation.html#eq-5-1": {"tex": "\\begin{equation*}\nx(t) = a_0 + \\sum_{n=1}^{\\infty}\\Big[a_n\\cos(n\\omega_0 t) + b_n\\sin(n\\omega_0 t)\\Big]. \\tag{5.1}\n\\end{equation*}"}, "ch07_fourier_series/01_fourier_series_derivation.html#eq-5-2": {"tex": "\\begin{equation*}\n\\int_{T}\\cos(k\\omega_0 t)\\,dt = \\begin{cases} T, & k = 0,\\\\ 0, & k \\neq 0,\\end{cases}\n\\qquad\n\\int_{T}\\sin(k\\omega_0 t)\\,dt = 0 \\ \\text{ for all integers } k. \\tag{5.2}\n\\end{equation*}"}, "ch07_fourier_series/01_fourier_series_derivation.html#eq-5-3": {"tex": "\\begin{equation*}\n\\begin{aligned}\n\\int_T \\cos(m\\omega_0 t)\\cos(n\\omega_0 t)\\,dt &= \\begin{cases} 0, & m \\neq n,\\\\ T/2, & m = n \\ge 1,\\\\ T, & m = n = 0,\\end{cases}\\\\[4pt]\n\\int_T \\sin(m\\omega_0 t)\\sin(n\\omega_0 t)\\,dt &= \\begin{cases} 0, & m \\neq n,\\\\ T/2, & m = n \\ge 1,\\end{cases}\\\\[4pt]\n\\int_T \\sin(m\\omega_0 t)\\cos(n\\omega_0 t)\\,dt &= 0 \\quad \\text{for all } m, n.\n\\end{aligned} \\tag{5.3}\n\\end{equation*}"}, "ch07_fourier_series/01_fourier_series_derivation.html#eq-5-4": {"tex": "\\begin{equation*}\na_0 = \\frac{1}{T}\\int_T x(t)\\,dt. \\tag{5.4}\n\\end{equation*}"}, "ch07_fourier_series/01_fourier_series_derivation.html#eq-5-5": {"tex": "\\begin{equation*}\na_n = \\frac{2}{T}\\int_T x(t)\\cos(n\\omega_0 t)\\,dt, \\qquad n \\ge 1. \\tag{5.5}\n\\end{equation*}"}, "ch07_fourier_series/01_fourier_series_derivation.html#eq-5-6": {"tex": "\\begin{equation*}\nb_n = \\frac{2}{T}\\int_T x(t)\\sin(n\\omega_0 t)\\,dt, \\qquad n \\ge 1. \\tag{5.6}\n\\end{equation*}"}, "ch07_fourier_series/01_fourier_series_derivation.html#eq-5-7": {"tex": "\\begin{equation*}\nb_n = \\begin{cases}\\dfrac{4}{n\\pi}, & n \\text{ odd},\\\\[6pt] 0, & n \\text{ even},\\end{cases}\n\\qquad\\qquad\nx(t) = \\frac{4}{\\pi}\\left[\\sin(\\omega_0 t) + \\frac{\\sin(3\\omega_0 t)}{3} + \\frac{\\sin(5\\omega_0 t)}{5} + \\cdots\\right]. \\tag{5.7}\n\\end{equation*}"}, "ch07_fourier_series/01_fourier_series_derivation.html#eq-5-8": {"tex": "\\begin{equation*}\nb_n = \\frac{8}{T^2}\\cdot\\left(-\\frac{T}{2}\\right)\\frac{(-1)^n\\,T}{2\\pi n} = \\frac{2(-1)^{n+1}}{n\\pi},\n\\qquad\nx(t) = \\frac{2}{\\pi}\\left[\\sin(\\omega_0 t) - \\frac{\\sin(2\\omega_0 t)}{2} + \\frac{\\sin(3\\omega_0 t)}{3} - \\cdots\\right]. \\tag{5.8}\n\\end{equation*}"}, "ch07_fourier_series/01_fourier_series_derivation.html#eq-5-9": {"tex": "\\begin{equation*}\na_n = \\frac{2}{T}\\Big[1 - (-1)^n\\Big]\\int_0^{T/2}x(t)\\cos(n\\omega_0 t)\\,dt = \\begin{cases}\\dfrac{4}{T}\\displaystyle\\int_0^{T/2}x(t)\\cos(n\\omega_0 t)\\,dt, & n \\text{ odd},\\\\[10pt] 0, & n \\text{ even}.\\end{cases} \\tag{5.9}\n\\end{equation*}"}, "ch07_fourier_series/01_fourier_series_derivation.html#eq-5-10": {"tex": "\\begin{equation*}\na_n = -\\frac{16}{T^2}\\cdot\\frac{-2\\,T^2}{4\\pi^2 n^2} = \\frac{8}{\\pi^2 n^2}\\ (n \\text{ odd}),\n\\qquad\nx(t) = \\frac{8}{\\pi^2}\\left[\\cos(\\omega_0 t) + \\frac{\\cos(3\\omega_0 t)}{9} + \\frac{\\cos(5\\omega_0 t)}{25} + \\cdots\\right]. \\tag{5.10}\n\\end{equation*}"}, "ch07_fourier_series/01_fourier_series_derivation.html#eq-5-11": {"tex": "\\begin{equation*}\nx(t) = a_0 + \\sum_{n=1}^{\\infty}A_n\\cos(n\\omega_0 t + \\varphi_n), \\qquad A_n = \\sqrt{a_n^2 + b_n^2}, \\qquad \\varphi_n = \\operatorname{atan2}(-b_n,\\ a_n). \\tag{5.11}\n\\end{equation*}"}, "ch07_fourier_series/01_fourier_series_derivation.html#sec-5-1-2": {"tex": "\\begin{equation*}\nx(t) = a_0 + \\sum_{n=1}^{\\infty}\\Big[a_n\\cos(n\\omega_0 t) + b_n\\sin(n\\omega_0 t)\\Big]. \\tag{5.1}\n\\end{equation*}"}, "ch07_fourier_series/01_fourier_series_derivation.html#sec-5-1-3": {"tex": "\\int_{t_0}^{t_0 + T}\\cos(k\\omega_0 t)\\,dt = \\frac{\\sin\\big(k\\omega_0 t_0 + k\\omega_0 T\\big) - \\sin\\big(k\\omega_0 t_0\\big)}{k\\omega_0} = \\frac{\\sin\\big(k\\omega_0 t_0 + 2\\pi k\\big) - \\sin\\big(k\\omega_0 t_0\\big)}{k\\omega_0} = 0,"}, "ch07_fourier_series/01_fourier_series_derivation.html#sec-5-1-4": {"tex": "\\int_T x(t)\\,dt = a_0\\int_T dt + \\sum_{n=1}^{\\infty}\\Big[a_n\\underbrace{\\int_T \\cos(n\\omega_0 t)\\,dt}_{0} + b_n\\underbrace{\\int_T \\sin(n\\omega_0 t)\\,dt}_{0}\\Big] = a_0 T ."}, "ch07_fourier_series/01_fourier_series_derivation.html#sec-5-1-5": {"tex": "\\begin{aligned}\na_n &= \\frac{2}{T}\\left[\\int_0^{T/2}\\cos(n\\omega_0 t)\\,dt - \\int_{T/2}^{T}\\cos(n\\omega_0 t)\\,dt\\right]\\\\[4pt]\n&= \\frac{2}{T}\\cdot\\frac{1}{n\\omega_0}\\Big[\\big(\\sin(n\\pi) - \\sin 0\\big) - \\big(\\sin(2n\\pi) - \\sin(n\\pi)\\big)\\Big] = 0,\n\\end{aligned}"}, "ch07_fourier_series/01_fourier_series_derivation.html#sec-5-1-6": {"tex": "x \\text{ even:}\\qquad b_n = 0, \\qquad a_n = \\frac{4}{T}\\int_0^{T/2}x(t)\\cos(n\\omega_0 t)\\,dt ."}, "ch07_fourier_series/01_fourier_series_derivation.html#sec-5-1-7": {"tex": "A_n\\cos(n\\omega_0 t + \\varphi_n) = A_n\\cos\\varphi_n\\,\\cos(n\\omega_0 t) - A_n\\sin\\varphi_n\\,\\sin(n\\omega_0 t)."}, "ch13_filter_fundamentals/01_filter_types_specs.html#eq-8-1": {"tex": "\\begin{equation*}\ny[n] = \\sum_{k} h[k]\\, x[n-k] \\tag{8.1}\n\\end{equation*}"}, "ch13_filter_fundamentals/01_filter_types_specs.html#eq-8-2": {"tex": "\\begin{equation*}\nY(e^{j\\Omega}) = H(e^{j\\Omega})\\, X(e^{j\\Omega}). \\tag{8.2}\n\\end{equation*}"}, "ch13_filter_fundamentals/01_filter_types_specs.html#eq-8-3": {"tex": "\\begin{equation*}\nH_{\\text{HP}} = 1 - H_{\\text{LP}}, \\qquad\nH_{\\text{BP}} = H_{\\text{LP}}^{(\\Omega_2)} - H_{\\text{LP}}^{(\\Omega_1)}, \\qquad\nH_{\\text{BS}} = 1 - H_{\\text{BP}}, \\tag{8.3}\n\\end{equation*}"}, "ch13_filter_fundamentals/01_filter_types_specs.html#eq-8-4": {"tex": "\\begin{equation*}\nh_{\\text{LP}}[n] = \\frac{\\sin(\\Omega_c n)}{\\pi n} = \\frac{\\Omega_c}{\\pi}\\,\\operatorname{sinc}\\!\\left(\\frac{\\Omega_c n}{\\pi}\\right), \\qquad -\\infty < n < \\infty, \\tag{8.4}\n\\end{equation*}"}, "ch13_filter_fundamentals/01_filter_types_specs.html#eq-8-5": {"tex": "\\begin{equation*}\n\\begin{aligned}\nA_p &= 20\\log_{10}(1+\\delta_p) - 20\\log_{10}(1-\\delta_p) \\\\\n    &= 20\\log_{10}\\frac{1+\\delta_p}{1-\\delta_p} \\quad \\text{dB}.\n\\end{aligned} \\tag{8.5}\n\\end{equation*}"}, "ch13_filter_fundamentals/01_filter_types_specs.html#eq-8-6": {"tex": "\\begin{equation*}\nA_s = -20\\log_{10}\\delta_s \\quad \\text{dB}. \\tag{8.6}\n\\end{equation*}"}, "ch13_filter_fundamentals/01_filter_types_specs.html#eq-8-7": {"tex": "\\begin{equation*}\n\\delta_p = \\frac{10^{A_p/20} - 1}{10^{A_p/20} + 1}, \\qquad \\delta_s = 10^{-A_s/20}. \\tag{8.7}\n\\end{equation*}"}, "ch13_filter_fundamentals/01_filter_types_specs.html#eq-8-8": {"tex": "\\begin{equation*}\n|H(j\\omega)|^2 = \\frac{1}{1 + (\\omega/\\omega_c)^{2N}}. \\tag{8.8}\n\\end{equation*}"}, "ch13_filter_fundamentals/01_filter_types_specs.html#sec-8-1-1": {"tex": "\\begin{equation*}\ny[n] = \\sum_{k} h[k]\\, x[n-k] \\tag{8.1}\n\\end{equation*}"}, "ch13_filter_fundamentals/01_filter_types_specs.html#sec-8-1-2": {"tex": "\\begin{equation*}\nH_{\\text{HP}} = 1 - H_{\\text{LP}}, \\qquad\nH_{\\text{BP}} = H_{\\text{LP}}^{(\\Omega_2)} - H_{\\text{LP}}^{(\\Omega_1)}, \\qquad\nH_{\\text{BS}} = 1 - H_{\\text{BP}}, \\tag{8.3}\n\\end{equation*}"}, "ch13_filter_fundamentals/01_filter_types_specs.html#sec-8-1-3": {"tex": "h_{\\text{LP}}[n] = \\frac{1}{2\\pi}\\int_{-\\pi}^{\\pi} H_{\\text{LP}}(e^{j\\Omega})\\, e^{j\\Omega n}\\, d\\Omega\n= \\frac{1}{2\\pi}\\int_{-\\Omega_c}^{\\Omega_c} e^{j\\Omega n}\\, d\\Omega ."}, "ch13_filter_fundamentals/01_filter_types_specs.html#sec-8-1-4": {"tex": "\\begin{equation*}\n\\begin{aligned}\nA_p &= 20\\log_{10}(1+\\delta_p) - 20\\log_{10}(1-\\delta_p) \\\\\n    &= 20\\log_{10}\\frac{1+\\delta_p}{1-\\delta_p} \\quad \\text{dB}.\n\\end{aligned} \\tag{8.5}\n\\end{equation*}"}, "ch13_filter_fundamentals/01_filter_types_specs.html#sec-8-1-5": {"tex": "\\begin{equation*}\n|H(j\\omega)|^2 = \\frac{1}{1 + (\\omega/\\omega_c)^{2N}}. \\tag{8.8}\n\\end{equation*}"}, "ch12_spectral_estimation/02_power_spectral_density.html#eq-7-12": {"tex": "\\begin{equation*}\nS_x(e^{j\\Omega}) = \\lim_{N \\to \\infty} \\frac{1}{N}\\,\\mathbb{E}\\left\\{\\big|X_N(e^{j\\Omega})\\big|^2\\right\\}. \\tag{7.12}\n\\end{equation*}"}, "ch12_spectral_estimation/02_power_spectral_density.html#eq-7-13": {"tex": "\\begin{equation*}\n\\frac{1}{N}\\,\\mathbb{E}\\left\\{\\big|X_N(e^{j\\Omega})\\big|^2\\right\\} = \\sum_{k=-(N-1)}^{N-1}\\left(1 - \\frac{|k|}{N}\\right) R_x[k]\\,e^{-j\\Omega k}. \\tag{7.13}\n\\end{equation*}"}, "ch12_spectral_estimation/02_power_spectral_density.html#eq-7-14": {"tex": "\\begin{equation*}\n\\boxed{\\,S_x(e^{j\\Omega}) = \\sum_{k=-\\infty}^{\\infty} R_x[k]\\,e^{-j\\Omega k}\\,} \\tag{7.14}\n\\end{equation*}"}, "ch12_spectral_estimation/02_power_spectral_density.html#eq-7-15": {"tex": "\\begin{equation*}\nR_x[k] = \\frac{1}{2\\pi}\\int_{-\\pi}^{\\pi} S_x(e^{j\\Omega})\\,e^{j\\Omega k}\\,d\\Omega , \\tag{7.15}\n\\end{equation*}"}, "ch12_spectral_estimation/02_power_spectral_density.html#eq-7-16": {"tex": "\\begin{equation*}\nS_x(e^{j\\Omega}) = \\sigma_x^2\\,\\frac{1 - a^2}{1 - 2a\\cos\\Omega + a^2} = \\frac{\\sigma_w^2}{1 - 2a\\cos\\Omega + a^2}. \\tag{7.16}\n\\end{equation*}"}, "ch12_spectral_estimation/02_power_spectral_density.html#eq-7-17": {"tex": "\\begin{equation*}\nR_x[0] = \\mathbb{E}\\{x^2[n]\\} = \\frac{1}{2\\pi}\\int_{-\\pi}^{\\pi} S_x(e^{j\\Omega})\\,d\\Omega. \\tag{7.17}\n\\end{equation*}"}, "ch12_spectral_estimation/02_power_spectral_density.html#eq-7-18": {"tex": "\\begin{equation*}\nS_x^{(1)}(f) = 2\\,S_x(f), \\qquad 0 < f < f_s/2, \\tag{7.18}\n\\end{equation*}"}, "ch12_spectral_estimation/02_power_spectral_density.html#eq-7-19": {"tex": "\\begin{equation*}\nS_w(e^{j\\Omega}) = \\sum_k \\sigma_w^2\\,\\delta[k]\\,e^{-j\\Omega k} = \\sigma_w^2 \\quad \\text{for all } \\Omega. \\tag{7.19}\n\\end{equation*}"}, "ch12_spectral_estimation/02_power_spectral_density.html#eq-7-20": {"tex": "\\begin{equation*}\n\\boxed{\\,S_y(e^{j\\Omega}) = \\big|H(e^{j\\Omega})\\big|^2\\,S_x(e^{j\\Omega})\\,} \\tag{7.20}\n\\end{equation*}"}, "ch12_spectral_estimation/02_power_spectral_density.html#eq-7-21": {"tex": "\\begin{equation*}\n\\sigma_y^2 = \\frac{\\sigma_w^2}{2\\pi}\\int_{-\\pi}^{\\pi}\\big|H(e^{j\\Omega})\\big|^2 d\\Omega = \\sigma_w^2 \\sum_n h^2[n]. \\tag{7.21}\n\\end{equation*}"}, "ch12_spectral_estimation/02_power_spectral_density.html#sec-7-2-2": {"tex": "X_N(e^{j\\Omega}) = \\sum_{n=0}^{N-1} x[n]\\,e^{-j\\Omega n}."}, "ch12_spectral_estimation/02_power_spectral_density.html#sec-7-2-3": {"tex": "\\big|X_N(e^{j\\Omega})\\big|^2 = \\sum_{n=0}^{N-1} x[n]e^{-j\\Omega n}\\;\\sum_{m=0}^{N-1} x[m]e^{+j\\Omega m}\n= \\sum_{n=0}^{N-1}\\sum_{m=0}^{N-1} x[n]\\,x[m]\\,e^{-j\\Omega (n - m)}."}, "ch12_spectral_estimation/02_power_spectral_density.html#sec-7-2-4": {"tex": "S_x(e^{j\\Omega}) = R_x[0] + \\sum_{k=1}^{\\infty} R_x[k]\\big(e^{-j\\Omega k} + e^{j\\Omega k}\\big) = R_x[0] + 2\\sum_{k=1}^{\\infty} R_x[k]\\cos(\\Omega k)."}, "ch12_spectral_estimation/02_power_spectral_density.html#sec-7-2-5": {"tex": "\\begin{equation*}\nS_w(e^{j\\Omega}) = \\sum_k \\sigma_w^2\\,\\delta[k]\\,e^{-j\\Omega k} = \\sigma_w^2 \\quad \\text{for all } \\Omega. \\tag{7.19}\n\\end{equation*}"}, "ch12_spectral_estimation/02_power_spectral_density.html#sec-7-2-6": {"tex": "\\begin{aligned}\nR_y[k] = \\mathbb{E}\\{y[n]\\,y[n+k]\\}\n&= \\mathbb{E}\\Big\\{\\sum_i h[i]\\,x[n-i]\\;\\sum_l h[l]\\,x[n+k-l]\\Big\\} \\\\\n&= \\sum_i\\sum_l h[i]\\,h[l]\\;\\mathbb{E}\\{x[n-i]\\,x[n+k-l]\\} \\\\\n&= \\sum_i\\sum_l h[i]\\,h[l]\\;R_x[k + i - l].\n\\end{aligned}"}, "ch12_spectral_estimation/01_random_processes.html#eq-7-1": {"tex": "\\begin{equation*}\n\\mu_x[n] = \\mathbb{E}\\{x[n]\\}. \\tag{7.1}\n\\end{equation*}"}, "ch12_spectral_estimation/01_random_processes.html#eq-7-2": {"tex": "\\begin{equation*}\nR_x[n_1, n_2] = \\mathbb{E}\\{x[n_1]\\,x[n_2]\\}, \\tag{7.2}\n\\end{equation*}"}, "ch12_spectral_estimation/01_random_processes.html#eq-7-3": {"tex": "\\begin{equation*}\nR_s[n_1, n_2] = \\frac{A^2}{2}\\cos(\\Omega_0 k). \\tag{7.3}\n\\end{equation*}"}, "ch12_spectral_estimation/01_random_processes.html#eq-7-4": {"tex": "\\begin{equation*}\n\\mu_x[n] = \\mu_x \\ \\text{(a constant)}, \\qquad R_x[n, n + k] = R_x[k] \\ \\text{(a function of the lag only)}. \\tag{7.4}\n\\end{equation*}"}, "ch12_spectral_estimation/01_random_processes.html#eq-7-5": {"tex": "\\begin{equation*}\n\\sigma_s^2[n] = \\operatorname{Var}\\Big\\{\\sum_{i=1}^{n} w[i]\\Big\\} = \\sum_{i=1}^{n} \\operatorname{Var}\\{w[i]\\} = n\\sigma^2, \\tag{7.5}\n\\end{equation*}"}, "ch12_spectral_estimation/01_random_processes.html#eq-7-6": {"tex": "\\begin{equation*}\n\\operatorname{Var}\\{\\hat{\\mu}_N\\} = \\frac{1}{N}\\sum_{k=-(N-1)}^{N-1}\\left(1 - \\frac{|k|}{N}\\right) C_x[k]. \\tag{7.6}\n\\end{equation*}"}, "ch12_spectral_estimation/01_random_processes.html#eq-7-7": {"tex": "\\begin{equation*}\nR_w[k] = \\sigma_w^2\\,\\delta[k]. \\tag{7.7}\n\\end{equation*}"}, "ch12_spectral_estimation/01_random_processes.html#eq-7-8": {"tex": "\\begin{equation*}\nx[n] = a\\,x[n-1] + w[n], \\qquad |a| < 1, \\tag{7.8}\n\\end{equation*}"}, "ch12_spectral_estimation/01_random_processes.html#eq-7-9": {"tex": "\\begin{equation*}\nR_x[k] = \\frac{\\sigma_w^2}{1 - a^2}\\,a^{|k|}. \\tag{7.9}\n\\end{equation*}"}, "ch12_spectral_estimation/01_random_processes.html#eq-7-10": {"tex": "\\begin{equation*}\n\\hat{r}_x^{\\,b}[k] = \\frac{1}{N}\\sum_{n=0}^{N-1-k} x[n]\\,x[n+k], \\qquad\n\\hat{r}_x^{\\,u}[k] = \\frac{1}{N - k}\\sum_{n=0}^{N-1-k} x[n]\\,x[n+k]. \\tag{7.10}\n\\end{equation*}"}, "ch12_spectral_estimation/01_random_processes.html#eq-7-11": {"tex": "\\begin{equation*}\n\\mathbb{E}\\{\\hat{r}_x^{\\,u}[k]\\} = \\frac{N - k}{N - k}R_x[k] = R_x[k], \\qquad\n\\mathbb{E}\\{\\hat{r}_x^{\\,b}[k]\\} = \\frac{N - k}{N}R_x[k] = \\left(1 - \\frac{k}{N}\\right)R_x[k]. \\tag{7.11}\n\\end{equation*}"}, "ch12_spectral_estimation/01_random_processes.html#sec-7-1-1": {"tex": "x[n] = A\\cos(\\Omega_0 n + \\Phi) + w[n], \\qquad \\Omega_0 = 2\\pi \\cdot \\frac{10}{160}\\ \\text{rad/sample}."}, "ch12_spectral_estimation/01_random_processes.html#sec-7-1-2": {"tex": "\\begin{equation*}\n\\mu_x[n] = \\mathbb{E}\\{x[n]\\}. \\tag{7.1}\n\\end{equation*}"}, "ch12_spectral_estimation/01_random_processes.html#sec-7-1-3": {"tex": "\\begin{equation*}\n\\mu_x[n] = \\mu_x \\ \\text{(a constant)}, \\qquad R_x[n, n + k] = R_x[k] \\ \\text{(a function of the lag only)}. \\tag{7.4}\n\\end{equation*}"}, "ch12_spectral_estimation/01_random_processes.html#sec-7-1-4": {"tex": "\\hat{\\mu}_N = \\frac{1}{N}\\sum_{n=0}^{N-1} x[n]."}, "ch12_spectral_estimation/01_random_processes.html#sec-7-1-5": {"tex": "\\begin{equation*}\nR_w[k] = \\sigma_w^2\\,\\delta[k]. \\tag{7.7}\n\\end{equation*}"}, "ch12_spectral_estimation/01_random_processes.html#sec-7-1-6": {"tex": "\\begin{equation*}\n\\hat{r}_x^{\\,b}[k] = \\frac{1}{N}\\sum_{n=0}^{N-1-k} x[n]\\,x[n+k], \\qquad\n\\hat{r}_x^{\\,u}[k] = \\frac{1}{N - k}\\sum_{n=0}^{N-1-k} x[n]\\,x[n+k]. \\tag{7.10}\n\\end{equation*}"}, "ch12_spectral_estimation/03_nonparametric_psd.html#eq-7-22": {"tex": "\\begin{equation*}\n\\hat{S}_P(e^{j\\Omega}) = \\frac{1}{N}\\left|\\sum_{n=0}^{N-1} x[n]\\,e^{-j\\Omega n}\\right|^2 . \\tag{7.22}\n\\end{equation*}"}, "ch12_spectral_estimation/03_nonparametric_psd.html#eq-7-23": {"tex": "\\begin{equation*}\n\\hat{S}_P(f_k) = \\frac{c_k}{N f_s}\\,\\big|X[k]\\big|^2, \\qquad f_k = \\frac{k f_s}{N}, \\qquad c_k = \\begin{cases} 1, & k = 0 \\text{ or } k = N/2, \\\\ 2, & \\text{otherwise}. \\end{cases} \\tag{7.23}\n\\end{equation*}"}, "ch12_spectral_estimation/03_nonparametric_psd.html#eq-7-24": {"tex": "\\begin{equation*}\n\\hat{S}_P(e^{j\\Omega}) = \\sum_{k=-(N-1)}^{N-1} \\hat{r}_x^{\\,b}[k]\\,e^{-j\\Omega k}. \\tag{7.24}\n\\end{equation*}"}, "ch12_spectral_estimation/03_nonparametric_psd.html#eq-7-25": {"tex": "\\begin{equation*}\nF_N(\\Omega) = \\frac{1}{N}\\,\\big|W_R(e^{j\\Omega})\\big|^2 = \\frac{1}{N}\\,\\frac{\\sin^2(N\\Omega/2)}{\\sin^2(\\Omega/2)} . \\tag{7.25}\n\\end{equation*}"}, "ch12_spectral_estimation/03_nonparametric_psd.html#eq-7-26": {"tex": "\\begin{equation*}\n\\mathbb{E}\\{\\hat{S}_P(e^{j\\Omega})\\} = \\frac{1}{2\\pi}\\int_{-\\pi}^{\\pi} S_x(e^{j\\theta})\\,F_N(\\Omega - \\theta)\\,d\\theta . \\tag{7.26}\n\\end{equation*}"}, "ch12_spectral_estimation/03_nonparametric_psd.html#eq-7-27": {"tex": "\\begin{equation*}\n\\hat{S}_M(e^{j\\Omega}) = \\frac{1}{N U}\\left|\\sum_{n=0}^{N-1} w[n]\\,x[n]\\,e^{-j\\Omega n}\\right|^2, \\qquad U = \\frac{1}{N}\\sum_{n=0}^{N-1} w^2[n], \\tag{7.27}\n\\end{equation*}"}, "ch12_spectral_estimation/03_nonparametric_psd.html#eq-7-28": {"tex": "\\begin{equation*}\n\\hat{S}_P(f) \\approx S_x(f)\\,\\frac{\\chi^2_2}{2}, \\qquad \\operatorname{Var}\\{\\hat{S}_P(f)\\} \\approx S_x^2(f), \\qquad 0 < f < f_s/2 . \\tag{7.28}\n\\end{equation*}"}, "ch12_spectral_estimation/03_nonparametric_psd.html#eq-7-29": {"tex": "\\begin{equation*}\n\\hat{S}_B(e^{j\\Omega}) = \\frac{1}{K}\\sum_{i=0}^{K-1}\\frac{1}{L}\\left|\\sum_{n=0}^{L-1} x_i[n]\\,e^{-j\\Omega n}\\right|^2 . \\tag{7.29}\n\\end{equation*}"}, "ch12_spectral_estimation/03_nonparametric_psd.html#eq-7-30": {"tex": "\\begin{equation*}\n\\underbrace{\\frac{f_s}{L}}_{\\text{resolution (Hz)}} \\times \\underbrace{\\frac{\\operatorname{Var}\\{\\hat{S}_B\\}}{S_x^2}}_{\\approx 1/K} \\approx \\frac{f_s}{L}\\cdot\\frac{L}{N} = \\frac{1}{T}. \\tag{7.30}\n\\end{equation*}"}, "ch12_spectral_estimation/03_nonparametric_psd.html#eq-7-31": {"tex": "\\begin{equation*}\n\\hat{S}_W(f) = \\frac{1}{K}\\sum_{i=0}^{K-1}\\frac{1}{f_s\\sum_{n=0}^{L-1} w^2[n]}\\left|\\sum_{n=0}^{L-1} w[n]\\,x_i[n]\\,e^{-j2\\pi f n/f_s}\\right|^2 , \\tag{7.31}\n\\end{equation*}"}, "ch12_spectral_estimation/03_nonparametric_psd.html#eq-7-32": {"tex": "\\begin{equation*}\n\\nu \\approx \\frac{2K}{1 + 2\\sum_{m=1}^{K-1}\\left(1 - \\frac{m}{K}\\right)\\rho^2(m)}, \\qquad \\operatorname{Var}\\{\\hat{S}_W(f)\\} \\approx \\frac{2}{\\nu}\\,S_x^2(f). \\tag{7.32}\n\\end{equation*}"}, "ch12_spectral_estimation/03_nonparametric_psd.html#eq-7-33": {"tex": "\\begin{equation*}\n\\frac{\\nu\\,\\hat{S}_W(f)}{q_{1-\\alpha/2}} \\;\\le\\; S_x(f) \\;\\le\\; \\frac{\\nu\\,\\hat{S}_W(f)}{q_{\\alpha/2}} \\quad\\text{with probability } 1 - \\alpha. \\tag{7.33}\n\\end{equation*}"}, "ch12_spectral_estimation/03_nonparametric_psd.html#sec-7-3-1": {"tex": "\\begin{equation*}\n\\hat{S}_P(e^{j\\Omega}) = \\frac{1}{N}\\left|\\sum_{n=0}^{N-1} x[n]\\,e^{-j\\Omega n}\\right|^2 . \\tag{7.22}\n\\end{equation*}"}, "ch12_spectral_estimation/03_nonparametric_psd.html#sec-7-3-2": {"tex": "\\mathbb{E}\\{\\hat{S}_P(e^{j\\Omega})\\} = \\sum_{k=-(N-1)}^{N-1} w_B[k]\\,R_x[k]\\,e^{-j\\Omega k}, \\qquad w_B[k] = \\begin{cases} 1 - |k|/N, & |k| < N, \\\\ 0, & \\text{otherwise}. \\end{cases}"}, "ch12_spectral_estimation/03_nonparametric_psd.html#sec-7-3-3": {"tex": "X[k] = \\sum_{n=0}^{N-1} x[n]\\cos\\!\\left(\\frac{2\\pi k n}{N}\\right) - j\\sum_{n=0}^{N-1} x[n]\\sin\\!\\left(\\frac{2\\pi k n}{N}\\right) = A_k - jB_k ."}, "ch12_spectral_estimation/03_nonparametric_psd.html#sec-7-3-4": {"tex": "\\begin{equation*}\n\\hat{S}_B(e^{j\\Omega}) = \\frac{1}{K}\\sum_{i=0}^{K-1}\\frac{1}{L}\\left|\\sum_{n=0}^{L-1} x_i[n]\\,e^{-j\\Omega n}\\right|^2 . \\tag{7.29}\n\\end{equation*}"}, "ch12_spectral_estimation/03_nonparametric_psd.html#sec-7-3-5": {"tex": "\\begin{equation*}\n\\hat{S}_W(f) = \\frac{1}{K}\\sum_{i=0}^{K-1}\\frac{1}{f_s\\sum_{n=0}^{L-1} w^2[n]}\\left|\\sum_{n=0}^{L-1} w[n]\\,x_i[n]\\,e^{-j2\\pi f n/f_s}\\right|^2 , \\tag{7.31}\n\\end{equation*}"}, "ch12_spectral_estimation/03_nonparametric_psd.html#sec-7-3-7": {"tex": "P\\left(q_{\\alpha/2} \\le \\frac{\\nu\\,\\hat{S}_W(f)}{S_x(f)} \\le q_{1-\\alpha/2}\\right) = 1 - \\alpha ."}, "ch12_spectral_estimation/04_parametric_psd.html#eq-7-34": {"tex": "\\begin{equation*}\nx[n] + a_1 x[n-1] + a_2 x[n-2] + \\cdots + a_p x[n-p] = w[n], \\tag{7.34}\n\\end{equation*}"}, "ch12_spectral_estimation/04_parametric_psd.html#eq-7-35": {"tex": "\\begin{equation*}\nS_x(e^{j\\Omega}) = \\frac{\\sigma^2}{\\big|A(e^{j\\Omega})\\big|^2} = \\frac{\\sigma^2}{\\left|1 + \\sum_{k=1}^{p} a_k e^{-j\\Omega k}\\right|^2}. \\tag{7.35}\n\\end{equation*}"}, "ch12_spectral_estimation/04_parametric_psd.html#eq-7-36": {"tex": "\\begin{equation*}\nS_x^{(1)}(f) = \\frac{2\\sigma^2}{f_s\\,\\big|A(e^{j2\\pi f/f_s})\\big|^2}, \\qquad 0 < f < f_s/2. \\tag{7.36}\n\\end{equation*}"}, "ch12_spectral_estimation/04_parametric_psd.html#eq-7-37": {"tex": "\\begin{equation*}\n\\sum_{k=1}^{p} a_k\\,R_x[m - k] = -R_x[m], \\quad m = 1, \\ldots, p, \\qquad\\qquad \\sigma^2 = R_x[0] + \\sum_{k=1}^{p} a_k\\,R_x[k]. \\tag{7.37}\n\\end{equation*}"}, "ch12_spectral_estimation/04_parametric_psd.html#eq-7-38": {"tex": "\\begin{equation*}\n\\underbrace{\\begin{bmatrix}\nR_x[0] & R_x[1] & \\cdots & R_x[p-1] \\\\\nR_x[1] & R_x[0] & \\cdots & R_x[p-2] \\\\\n\\vdots & \\vdots & \\ddots & \\vdots \\\\\nR_x[p-1] & R_x[p-2] & \\cdots & R_x[0]\n\\end{bmatrix}}_{\\mathbf{R}}\n\\begin{bmatrix} a_1 \\\\ a_2 \\\\ \\vdots \\\\ a_p \\end{bmatrix}\n= -\\begin{bmatrix} R_x[1] \\\\ R_x[2] \\\\ \\vdots \\\\ R_x[p] \\end{bmatrix}. \\tag{7.38}\n\\end{equation*}"}, "ch12_spectral_estimation/04_parametric_psd.html#eq-7-39": {"tex": "\\begin{equation*}\nk_{m+1} = -\\frac{\\Delta_m}{E_m}, \\qquad a_i^{(m+1)} = a_i^{(m)} + k_{m+1}\\,a_{m+1-i}^{(m)}, \\quad a_{m+1}^{(m+1)} = k_{m+1}, \\qquad E_{m+1} = E_m\\big(1 - k_{m+1}^2\\big). \\tag{7.39}\n\\end{equation*}"}, "ch12_spectral_estimation/04_parametric_psd.html#eq-7-40": {"tex": "\\begin{equation*}\nf_m[n] = f_{m-1}[n] + k_m\\,b_{m-1}[n-1], \\qquad b_m[n] = b_{m-1}[n-1] + k_m\\,f_{m-1}[n], \\tag{7.40}\n\\end{equation*}"}, "ch12_spectral_estimation/04_parametric_psd.html#eq-7-41": {"tex": "\\begin{equation*}\nk_m = \\frac{-2\\sum_{n=m}^{N-1} f_{m-1}[n]\\,b_{m-1}[n-1]}{\\sum_{n=m}^{N-1}\\Big(f_{m-1}^2[n] + b_{m-1}^2[n-1]\\Big)}. \\tag{7.41}\n\\end{equation*}"}, "ch12_spectral_estimation/04_parametric_psd.html#eq-7-42": {"tex": "\\begin{equation*}\n\\operatorname{FPE}(p) = E_p\\,\\frac{N + p}{N - p}, \\tag{7.42}\n\\end{equation*}"}, "ch12_spectral_estimation/04_parametric_psd.html#eq-7-43": {"tex": "\\begin{equation*}\n\\operatorname{AIC}(p) = N\\ln E_p + 2p. \\tag{7.43}\n\\end{equation*}"}, "ch12_spectral_estimation/04_parametric_psd.html#sec-7-4-1": {"tex": "\\begin{equation*}\nx[n] + a_1 x[n-1] + a_2 x[n-2] + \\cdots + a_p x[n-p] = w[n], \\tag{7.34}\n\\end{equation*}"}, "ch12_spectral_estimation/04_parametric_psd.html#sec-7-4-2": {"tex": "R_x[m] + \\sum_{k=1}^{p} a_k\\,R_x[m - k] = \\mathbb{E}\\{w[n]\\,x[n-m]\\}."}, "ch12_spectral_estimation/04_parametric_psd.html#sec-7-4-3": {"tex": "\\mathbf{R}_{m+1}\\,\\mathbf{a}^{(m)} = \\begin{bmatrix} E_m & 0 & \\cdots & 0 \\end{bmatrix}^T,"}, "ch12_spectral_estimation/04_parametric_psd.html#sec-7-4-4": {"tex": "f_m[n] = \\sum_{i=0}^{m} a_i^{(m)}\\,x[n - i], \\qquad b_m[n] = \\sum_{i=0}^{m} a_i^{(m)}\\,x[n - m + i], \\qquad a_0^{(m)} = 1."}, "ch12_spectral_estimation/04_parametric_psd.html#sec-7-4-6": {"tex": "\\begin{equation*}\n\\operatorname{FPE}(p) = E_p\\,\\frac{N + p}{N - p}, \\tag{7.42}\n\\end{equation*}"}, "ch18_ecg_preprocessing/01_ecg_noise_types.html#eq-12-1": {"tex": "\\begin{equation*}\nx[n] = s[n] + v[n]. \\tag{12.1}\n\\end{equation*}"}, "ch18_ecg_preprocessing/01_ecg_noise_types.html#eq-12-2": {"tex": "\\begin{equation*}\nx[n] = s[n]\\big(1 + m[n]\\big) = s[n] + s[n]\\,m[n], \\tag{12.2}\n\\end{equation*}"}, "ch18_ecg_preprocessing/01_ecg_noise_types.html#eq-12-3": {"tex": "\\begin{equation*}\nv_{\\text{th}} = \\sqrt{4 k T R B}, \\tag{12.3}\n\\end{equation*}"}, "ch18_ecg_preprocessing/01_ecg_noise_types.html#eq-12-4": {"tex": "\\begin{equation*}\nf_{\\text{alias}} = \\left| f - k f_s \\right|, \\tag{12.4}\n\\end{equation*}"}, "ch18_ecg_preprocessing/01_ecg_noise_types.html#eq-12-5": {"tex": "\\begin{equation*}\nP_s = \\frac{1}{N}\\sum_{n=0}^{N-1}\\big(s[n] - \\bar{s}\\big)^2, \\qquad\nP_v = \\frac{1}{N}\\sum_{n=0}^{N-1} v[n]^2, \\qquad\n\\mathrm{SNR}_{\\text{in}} = 10\\log_{10}\\frac{P_s}{P_v}\\ \\text{dB}, \\tag{12.5}\n\\end{equation*}"}, "ch18_ecg_preprocessing/01_ecg_noise_types.html#eq-12-6": {"tex": "\\begin{equation*}\ng = \\sqrt{\\frac{P_s}{P_v\\,10^{\\mathrm{SNR}/10}}}. \\tag{12.6}\n\\end{equation*}"}, "ch18_ecg_preprocessing/01_ecg_noise_types.html#eq-12-7": {"tex": "\\begin{equation*}\n\\mathrm{SNR}_{\\text{out}} = 10\\log_{10}\\frac{P_s}{\\frac{1}{N}\\sum_n \\big(\\hat{s}[n] - s[n]\\big)^2}, \\qquad\n\\Delta\\mathrm{SNR} = \\mathrm{SNR}_{\\text{out}} - \\mathrm{SNR}_{\\text{in}}\\ \\text{dB}. \\tag{12.7}\n\\end{equation*}"}, "ch18_ecg_preprocessing/01_ecg_noise_types.html#eq-12-8": {"tex": "\\begin{equation*}\n\\mathrm{RMSE} = \\sqrt{\\frac{1}{N}\\sum_{n}\\big(\\hat{s}[n] - s[n]\\big)^2}. \\tag{12.8}\n\\end{equation*}"}, "ch18_ecg_preprocessing/01_ecg_noise_types.html#eq-12-9": {"tex": "\\begin{equation*}\n\\mathrm{PRD} = 100\\sqrt{\\frac{\\sum_n \\big(\\hat{s}[n] - s[n]\\big)^2}{\\sum_n \\big(s[n] - \\bar{s}\\big)^2}}\\ \\%. \\tag{12.9}\n\\end{equation*}"}, "ch18_ecg_preprocessing/01_ecg_noise_types.html#eq-12-10": {"tex": "\\begin{equation*}\n\\rho = \\frac{\\sum_n (\\hat{s}[n] - \\bar{\\hat{s}})(s[n] - \\bar{s})}\n{\\sqrt{\\sum_n (\\hat{s}[n] - \\bar{\\hat{s}})^2}\\sqrt{\\sum_n (s[n] - \\bar{s})^2}}. \\tag{12.10}\n\\end{equation*}"}, "ch18_ecg_preprocessing/01_ecg_noise_types.html#eq-12-11": {"tex": "\\begin{equation*}\n\\mathrm{PRD} = 100 \\cdot 10^{-\\mathrm{SNR}_{\\text{out}}/20}\\ \\%, \\qquad\n\\mathrm{RMSE} = \\sqrt{P_s}\\cdot 10^{-\\mathrm{SNR}_{\\text{out}}/20}. \\tag{12.11}\n\\end{equation*}"}, "ch18_ecg_preprocessing/01_ecg_noise_types.html#sec-12-1-2": {"tex": "\\begin{equation*}\nx[n] = s[n] + v[n]. \\tag{12.1}\n\\end{equation*}"}, "ch18_ecg_preprocessing/01_ecg_noise_types.html#sec-12-1-3": {"tex": "\\begin{equation*}\nv_{\\text{th}} = \\sqrt{4 k T R B}, \\tag{12.3}\n\\end{equation*}"}, "ch18_ecg_preprocessing/01_ecg_noise_types.html#sec-12-1-6": {"tex": "x[n] = s[n] + g\\,v[n]."}, "ch18_ecg_preprocessing/01_ecg_noise_types.html#sec-12-1-7": {"tex": "\\begin{equation*}\n\\mathrm{SNR}_{\\text{out}} = 10\\log_{10}\\frac{P_s}{\\frac{1}{N}\\sum_n \\big(\\hat{s}[n] - s[n]\\big)^2}, \\qquad\n\\Delta\\mathrm{SNR} = \\mathrm{SNR}_{\\text{out}} - \\mathrm{SNR}_{\\text{in}}\\ \\text{dB}. \\tag{12.7}\n\\end{equation*}"}, "ch18_ecg_preprocessing/02_highpass_baseline_wander.html#eq-12-12": {"tex": "\\begin{equation*}\n\\mathrm{ST}_k(x) = x[r_k + n_{\\text{ST}}] - \\frac{1}{|W_{\\text{PR}}|}\\sum_{m \\in W_{\\text{PR}}} x[r_k + m], \\tag{12.12}\n\\end{equation*}"}, "ch18_ecg_preprocessing/02_highpass_baseline_wander.html#eq-12-13": {"tex": "\\begin{equation*}\nH(s) = \\frac{s}{s + \\omega_c}. \\tag{12.13}\n\\end{equation*}"}, "ch18_ecg_preprocessing/02_highpass_baseline_wander.html#eq-12-14": {"tex": "\\begin{equation*}\n|H(j\\omega)| = \\frac{\\omega}{\\sqrt{\\omega^2 + \\omega_c^2}}. \\tag{12.14}\n\\end{equation*}"}, "ch18_ecg_preprocessing/02_highpass_baseline_wander.html#eq-12-15": {"tex": "\\begin{equation*}\n\\angle H(j\\omega) = \\frac{\\pi}{2} - \\arctan\\frac{\\omega}{\\omega_c} = \\arctan\\frac{\\omega_c}{\\omega}, \\tag{12.15}\n\\end{equation*}"}, "ch18_ecg_preprocessing/02_highpass_baseline_wander.html#eq-12-16": {"tex": "\\begin{equation*}\nf_c < f_{\\text{HR,min}} = \\frac{\\text{HR}_{\\min}}{60}, \\tag{12.16}\n\\end{equation*}"}, "ch18_ecg_preprocessing/02_highpass_baseline_wander.html#eq-12-17": {"tex": "\\begin{equation*}\nN \\approx \\frac{A - 8}{2.285\\,\\Delta\\Omega} + 1, \\qquad \\Delta\\Omega = \\frac{2\\pi\\,\\Delta f}{f_s}. \\tag{12.17}\n\\end{equation*}"}, "ch18_ecg_preprocessing/02_highpass_baseline_wander.html#eq-12-18": {"tex": "\\begin{equation*}\n\\hat{b}[n] = \\operatorname{med}_{600}\\big(\\operatorname{med}_{200}(x)\\big)[n], \\qquad \\hat{s}[n] = x[n] - \\hat{b}[n], \\tag{12.18}\n\\end{equation*}"}, "ch18_ecg_preprocessing/02_highpass_baseline_wander.html#sec-12-2-1": {"tex": "\\begin{equation*}\n\\mathrm{ST}_k(x) = x[r_k + n_{\\text{ST}}] - \\frac{1}{|W_{\\text{PR}}|}\\sum_{m \\in W_{\\text{PR}}} x[r_k + m], \\tag{12.12}\n\\end{equation*}"}, "ch18_ecg_preprocessing/02_highpass_baseline_wander.html#sec-12-2-2": {"tex": "\\begin{equation*}\nH(s) = \\frac{s}{s + \\omega_c}. \\tag{12.13}\n\\end{equation*}"}, "ch18_ecg_preprocessing/02_highpass_baseline_wander.html#sec-12-2-4": {"tex": "\\begin{equation*}\nN \\approx \\frac{A - 8}{2.285\\,\\Delta\\Omega} + 1, \\qquad \\Delta\\Omega = \\frac{2\\pi\\,\\Delta f}{f_s}. \\tag{12.17}\n\\end{equation*}"}, "ch18_ecg_preprocessing/02_highpass_baseline_wander.html#sec-12-2-5": {"tex": "\\begin{equation*}\n\\hat{b}[n] = \\operatorname{med}_{600}\\big(\\operatorname{med}_{200}(x)\\big)[n], \\qquad \\hat{s}[n] = x[n] - \\hat{b}[n], \\tag{12.18}\n\\end{equation*}"}, "ch02_math_toolkit/01_complex_numbers.html#eq-2-1": {"tex": "\\begin{equation*}\ne^{j\\theta} = \\cos\\theta + j\\sin\\theta. \\tag{2.1}\n\\end{equation*}"}, "ch02_math_toolkit/01_complex_numbers.html#eq-2-2": {"tex": "\\begin{equation*}\n\\begin{aligned}\ne^{j\\theta} + e^{-j\\theta} &= 2\\cos\\theta &&\\Longrightarrow\\quad \\cos\\theta = \\frac{e^{j\\theta} + e^{-j\\theta}}{2}, \\\\[4pt]\ne^{j\\theta} - e^{-j\\theta} &= 2j\\sin\\theta &&\\Longrightarrow\\quad \\sin\\theta = \\frac{e^{j\\theta} - e^{-j\\theta}}{2j}.\n\\end{aligned} \\tag{2.2}\n\\end{equation*}"}, "ch02_math_toolkit/01_complex_numbers.html#eq-2-3": {"tex": "\\begin{equation*}\n\\hat{X}(f_0) = \\frac{2}{N}\\sum_{n=0}^{N-1} x[n]\\, e^{-j2\\pi f_0 n / f_s}. \\tag{2.3}\n\\end{equation*}"}, "ch02_math_toolkit/01_complex_numbers.html#sec-2-1-1": {"tex": "j^2 = -1."}, "ch02_math_toolkit/01_complex_numbers.html#sec-2-1-2": {"tex": "(a + jb) + (c + jd) = (a + c) + j(b + d)."}, "ch02_math_toolkit/01_complex_numbers.html#sec-2-1-3": {"tex": "a = r\\cos\\theta, \\qquad b = r\\sin\\theta, \\qquad r = \\sqrt{a^2 + b^2}, \\qquad \\theta = \\operatorname{atan2}(b, a)."}, "ch02_math_toolkit/01_complex_numbers.html#sec-2-1-4": {"tex": "\\begin{equation*}\ne^{j\\theta} = \\cos\\theta + j\\sin\\theta. \\tag{2.1}\n\\end{equation*}"}, "ch02_math_toolkit/01_complex_numbers.html#sec-2-1-5": {"tex": "z_1 z_2 = r_1 e^{j\\theta_1}\\, r_2 e^{j\\theta_2} = (r_1 r_2)\\, e^{j(\\theta_1 + \\theta_2)}."}, "ch02_math_toolkit/01_complex_numbers.html#sec-2-1-6": {"tex": "e^{j\\omega t} = \\cos(\\omega t) + j\\sin(\\omega t)"}, "ch02_math_toolkit/01_complex_numbers.html#sec-2-1-7": {"tex": "\\begin{aligned}\nA\\cos(\\omega_0 t + \\varphi)\\, e^{-j\\omega_0 t}\n&= \\frac{A}{2}\\left(e^{j(\\omega_0 t + \\varphi)} + e^{-j(\\omega_0 t + \\varphi)}\\right) e^{-j\\omega_0 t} \\\\[4pt]\n&= \\frac{A}{2} e^{j\\varphi} \\;+\\; \\frac{A}{2} e^{-j(2\\omega_0 t + \\varphi)} .\n\\end{aligned}"}, "ch02_math_toolkit/03_signals_as_vectors.html#eq-2-4": {"tex": "\\begin{equation*}\n\\langle \\mathbf{x}, \\mathbf{y} \\rangle = \\sum_{n=0}^{N-1} x[n]\\,y[n] = \\mathbf{x}^{\\mathsf T}\\mathbf{y}. \\tag{2.4}\n\\end{equation*}"}, "ch02_math_toolkit/03_signals_as_vectors.html#eq-2-5": {"tex": "\\begin{equation*}\n\\|\\mathbf{x}\\| = \\sqrt{\\langle \\mathbf{x}, \\mathbf{x} \\rangle} = \\sqrt{\\sum_{n=0}^{N-1} x[n]^2}, \\qquad E_x = \\|\\mathbf{x}\\|^2. \\tag{2.5}\n\\end{equation*}"}, "ch02_math_toolkit/03_signals_as_vectors.html#eq-2-6": {"tex": "\\begin{equation*}\n|\\langle \\mathbf{x}, \\mathbf{y} \\rangle| \\le \\|\\mathbf{x}\\|\\,\\|\\mathbf{y}\\|, \\tag{2.6}\n\\end{equation*}"}, "ch02_math_toolkit/03_signals_as_vectors.html#eq-2-7": {"tex": "\\begin{equation*}\n\\cos\\theta = \\frac{\\langle \\mathbf{x}, \\mathbf{y} \\rangle}{\\|\\mathbf{x}\\|\\,\\|\\mathbf{y}\\|}, \\qquad\n\\rho_{xy} = \\frac{\\langle \\tilde{\\mathbf{x}}, \\tilde{\\mathbf{y}} \\rangle}{\\|\\tilde{\\mathbf{x}}\\|\\,\\|\\tilde{\\mathbf{y}}\\|}, \\quad \\tilde{\\mathbf{x}} = \\mathbf{x} - \\bar{x}\\,\\mathbf{1}. \\tag{2.7}\n\\end{equation*}"}, "ch02_math_toolkit/03_signals_as_vectors.html#eq-2-8": {"tex": "\\begin{equation*}\n\\hat{\\mathbf{x}} = \\frac{\\langle \\mathbf{x}, \\mathbf{y} \\rangle}{\\langle \\mathbf{y}, \\mathbf{y} \\rangle}\\,\\mathbf{y}, \\qquad \\langle \\mathbf{x} - \\hat{\\mathbf{x}},\\, \\mathbf{y} \\rangle = 0. \\tag{2.8}\n\\end{equation*}"}, "ch02_math_toolkit/03_signals_as_vectors.html#eq-2-9": {"tex": "\\begin{equation*}\n\\mathbf{A}^{\\mathsf T}\\mathbf{A}\\,\\mathbf{c} = \\mathbf{A}^{\\mathsf T}\\mathbf{x}\n\\quad\\Longrightarrow\\quad\n\\mathbf{c} = (\\mathbf{A}^{\\mathsf T}\\mathbf{A})^{-1}\\mathbf{A}^{\\mathsf T}\\mathbf{x}, \\qquad\n\\hat{\\mathbf{x}} = \\mathbf{A}\\mathbf{c}. \\tag{2.9}\n\\end{equation*}"}, "ch02_math_toolkit/03_signals_as_vectors.html#eq-2-10": {"tex": "\\begin{equation*}\nc_k = \\langle \\mathbf{x}, \\mathbf{q}_k \\rangle, \\qquad \\hat{\\mathbf{x}} = \\sum_{k} \\langle \\mathbf{x}, \\mathbf{q}_k \\rangle\\, \\mathbf{q}_k . \\tag{2.10}\n\\end{equation*}"}, "ch02_math_toolkit/03_signals_as_vectors.html#eq-2-11": {"tex": "\\begin{equation*}\n\\|\\mathbf{x}\\|^2 = \\sum_{k} c_k^2 . \\tag{2.11}\n\\end{equation*}"}, "ch02_math_toolkit/03_signals_as_vectors.html#eq-2-12": {"tex": "\\begin{equation*}\n\\mathbf{v}_k = \\mathbf{a}_k - \\sum_{i=1}^{k-1} \\langle \\mathbf{a}_k, \\mathbf{q}_i \\rangle\\, \\mathbf{q}_i, \\qquad \\mathbf{q}_k = \\frac{\\mathbf{v}_k}{\\|\\mathbf{v}_k\\|}. \\tag{2.12}\n\\end{equation*}"}, "ch02_math_toolkit/03_signals_as_vectors.html#eq-2-13": {"tex": "\\begin{equation*}\n\\sum_{n=0}^{N-1} \\cos\\!\\Big(\\frac{2\\pi k n}{N}\\Big)\\cos\\!\\Big(\\frac{2\\pi m n}{N}\\Big) = \\begin{cases} N/2, & k = m, \\\\ 0, & k \\neq m, \\end{cases} \\qquad 0 < k, m < \\tfrac{N}{2}. \\tag{2.13}\n\\end{equation*}"}, "ch02_math_toolkit/03_signals_as_vectors.html#eq-2-14": {"tex": "\\begin{equation*}\n\\langle \\mathbf{x}, \\mathbf{y} \\rangle = \\sum_{n=0}^{N-1} x[n]\\,y^*[n], \\qquad \\langle \\mathbf{x}, \\mathbf{x} \\rangle = \\sum_{n=0}^{N-1} |x[n]|^2 \\ge 0. \\tag{2.14}\n\\end{equation*}"}, "ch02_math_toolkit/03_signals_as_vectors.html#eq-2-15": {"tex": "\\begin{equation*}\nX[k] = \\langle \\mathbf{x}, \\mathbf{e}_k \\rangle = \\sum_{n=0}^{N-1} x[n]\\,e^{-j2\\pi k n/N}. \\tag{2.15}\n\\end{equation*}"}, "ch02_math_toolkit/03_signals_as_vectors.html#sec-2-2-1": {"tex": "\\mathbf{x} = \\big(x[0],\\, x[1],\\, \\ldots,\\, x[N-1]\\big)^{\\mathsf T} \\in \\mathbb{R}^N ."}, "ch02_math_toolkit/03_signals_as_vectors.html#sec-2-2-2": {"tex": "\\begin{equation*}\n\\langle \\mathbf{x}, \\mathbf{y} \\rangle = \\sum_{n=0}^{N-1} x[n]\\,y[n] = \\mathbf{x}^{\\mathsf T}\\mathbf{y}. \\tag{2.4}\n\\end{equation*}"}, "ch02_math_toolkit/03_signals_as_vectors.html#sec-2-2-3": {"tex": "\\begin{equation*}\n|\\langle \\mathbf{x}, \\mathbf{y} \\rangle| \\le \\|\\mathbf{x}\\|\\,\\|\\mathbf{y}\\|, \\tag{2.6}\n\\end{equation*}"}, "ch02_math_toolkit/03_signals_as_vectors.html#sec-2-2-4": {"tex": "\\begin{equation*}\n\\hat{\\mathbf{x}} = \\frac{\\langle \\mathbf{x}, \\mathbf{y} \\rangle}{\\langle \\mathbf{y}, \\mathbf{y} \\rangle}\\,\\mathbf{y}, \\qquad \\langle \\mathbf{x} - \\hat{\\mathbf{x}},\\, \\mathbf{y} \\rangle = 0. \\tag{2.8}\n\\end{equation*}"}, "ch02_math_toolkit/03_signals_as_vectors.html#sec-2-2-5": {"tex": "\\begin{equation*}\nc_k = \\langle \\mathbf{x}, \\mathbf{q}_k \\rangle, \\qquad \\hat{\\mathbf{x}} = \\sum_{k} \\langle \\mathbf{x}, \\mathbf{q}_k \\rangle\\, \\mathbf{q}_k . \\tag{2.10}\n\\end{equation*}"}, "ch02_math_toolkit/03_signals_as_vectors.html#sec-2-2-6": {"tex": "\\langle c_k, c_m \\rangle = \\frac{1}{2}\\sum_{n=0}^{N-1} \\cos\\!\\Big(\\frac{2\\pi (k - m) n}{N}\\Big) + \\frac{1}{2}\\sum_{n=0}^{N-1} \\cos\\!\\Big(\\frac{2\\pi (k + m) n}{N}\\Big)."}, "ch02_math_toolkit/03_signals_as_vectors.html#sec-2-2-7": {"tex": "\\|\\mathbf{w} - \\bar{w}\\mathbf{1}\\|^2 = \\sum_{m} w[m]^2 - 2\\bar{w}\\sum_m w[m] + M\\bar{w}^2 = \\sum_{m} w[m]^2 - \\frac{1}{M}\\Big(\\sum_m w[m]\\Big)^2 ,"}, "ch02_math_toolkit/04_calculus_for_signals.html#eq-2-16": {"tex": "\\begin{equation*}\n\\frac{x(t + h) - x(t)}{h} = x'(t) + \\frac{h}{2}x''(t) + O(h^2). \\tag{2.16}\n\\end{equation*}"}, "ch02_math_toolkit/04_calculus_for_signals.html#eq-2-17": {"tex": "\\begin{equation*}\n\\frac{x(t + h) - x(t - h)}{2h} = x'(t) + \\frac{h^2}{6}x'''(t) + O(h^4). \\tag{2.17}\n\\end{equation*}"}, "ch02_math_toolkit/04_calculus_for_signals.html#eq-2-18": {"tex": "\\begin{equation*}\n|H_{\\text{ideal}}| = \\omega = \\frac{\\Omega}{T_s}, \\qquad\n|H_{\\text{backward}}| = \\frac{2\\,|\\sin(\\Omega/2)|}{T_s}, \\qquad\n|H_{\\text{central}}| = \\frac{|\\sin\\Omega|}{T_s}, \\tag{2.18}\n\\end{equation*}"}, "ch02_math_toolkit/04_calculus_for_signals.html#eq-2-19": {"tex": "\\begin{equation*}\n\\operatorname{Var}\\!\\left[\\frac{v[n] - v[n-1]}{T_s}\\right] = \\frac{\\sigma^2 + \\sigma^2}{T_s^2} = \\frac{2\\sigma^2}{T_s^2}, \\qquad\n\\operatorname{Var}\\!\\left[\\frac{v[n+1] - v[n-1]}{2T_s}\\right] = \\frac{2\\sigma^2}{4T_s^2} = \\frac{\\sigma^2}{2T_s^2}. \\tag{2.19}\n\\end{equation*}"}, "ch02_math_toolkit/04_calculus_for_signals.html#eq-2-20": {"tex": "\\begin{equation*}\n\\int_a^b x(t)\\,dt \\approx T_s\\left(\\frac{x[0]}{2} + x[1] + \\cdots + x[N-1] + \\frac{x[N]}{2}\\right). \\tag{2.20}\n\\end{equation*}"}, "ch02_math_toolkit/04_calculus_for_signals.html#eq-2-21": {"tex": "\\begin{equation*}\nE_{\\text{trap}} \\approx \\frac{(b - a)\\,h^2}{12}\\,\\overline{x''}, \\tag{2.21}\n\\end{equation*}"}, "ch02_math_toolkit/04_calculus_for_signals.html#eq-2-22": {"tex": "\\begin{equation*}\n\\operatorname{Var}\\big(y_{\\text{noise}}[n]\\big) = T_s^2\\,(n + 1)\\,\\sigma^2 \\quad\\Longrightarrow\\quad \\text{std} = T_s\\,\\sigma\\sqrt{n + 1} = \\sigma\\sqrt{T_s\\,t}. \\tag{2.22}\n\\end{equation*}"}, "ch02_math_toolkit/04_calculus_for_signals.html#eq-2-23": {"tex": "\\begin{equation*}\n\\delta_\\varepsilon(t) = \\begin{cases} 1/\\varepsilon, & |t| < \\varepsilon/2, \\\\ 0, & \\text{otherwise,} \\end{cases} \\qquad \\int_{-\\infty}^{\\infty} \\delta_\\varepsilon(t)\\,dt = 1 \\text{ for every } \\varepsilon. \\tag{2.23}\n\\end{equation*}"}, "ch02_math_toolkit/04_calculus_for_signals.html#eq-2-24": {"tex": "\\begin{equation*}\n\\int_{-\\infty}^{\\infty} x(t)\\,\\delta(t - t_0)\\,dt = x(t_0). \\tag{2.24}\n\\end{equation*}"}, "ch02_math_toolkit/04_calculus_for_signals.html#eq-2-25": {"tex": "\\begin{equation*}\n\\int_a^b f(t)\\,g'(t)\\,dt = \\Big[f(t)\\,g(t)\\Big]_a^b - \\int_a^b f'(t)\\,g(t)\\,dt. \\tag{2.25}\n\\end{equation*}"}, "ch02_math_toolkit/04_calculus_for_signals.html#eq-2-26": {"tex": "\\begin{equation*}\n\\int_0^\\infty t\\,e^{-at}\\,dt = \\Big[-\\frac{t\\,e^{-at}}{a}\\Big]_0^\\infty + \\frac{1}{a}\\int_0^\\infty e^{-at}\\,dt = 0 + \\frac{1}{a}\\cdot\\frac{1}{a} = \\frac{1}{a^2}. \\tag{2.26}\n\\end{equation*}"}, "ch02_math_toolkit/04_calculus_for_signals.html#eq-2-27": {"tex": "\\begin{equation*}\n\\int_{-\\infty}^{\\infty} e^{-t^2}\\,dt = \\sqrt{\\pi}, \\qquad \\int_{-\\infty}^{\\infty} e^{-s^2/(2\\sigma^2)}\\,ds = \\sigma\\sqrt{2\\pi}. \\tag{2.27}\n\\end{equation*}"}, "ch02_math_toolkit/04_calculus_for_signals.html#eq-2-28": {"tex": "\\begin{equation*}\n\\sum_{n=0}^{N-1} r^n = \\frac{1 - r^N}{1 - r}, \\qquad r \\ne 1, \\tag{2.28}\n\\end{equation*}"}, "ch02_math_toolkit/04_calculus_for_signals.html#eq-2-29": {"tex": "\\begin{equation*}\n\\sum_{n=0}^{\\infty} r^n = \\frac{1}{1 - r}, \\qquad |r| < 1. \\tag{2.29}\n\\end{equation*}"}, "ch02_math_toolkit/04_calculus_for_signals.html#eq-2-30": {"tex": "\\begin{equation*}\nf(x_0 + \\Delta) = f(x_0) + f'(x_0)\\,\\Delta + \\frac{f''(\\xi)}{2}\\,\\Delta^2 \\approx f(x_0) + f'(x_0)\\,\\Delta, \\tag{2.30}\n\\end{equation*}"}, "ch02_math_toolkit/04_calculus_for_signals.html#sec-2-3-1": {"tex": "x'(t) = \\frac{dx}{dt} = \\lim_{h \\to 0} \\frac{x(t + h) - x(t)}{h}."}, "ch02_math_toolkit/04_calculus_for_signals.html#sec-2-3-2": {"tex": "\\frac{x[n] - x[n-1]}{T_s} = \\frac{1 - e^{-j\\Omega}}{T_s}\\,e^{j\\Omega n} = \\frac{e^{-j\\Omega/2}\\big(e^{j\\Omega/2} - e^{-j\\Omega/2}\\big)}{T_s}\\,e^{j\\Omega n} = \\frac{2j\\sin(\\Omega/2)}{T_s}\\,e^{-j\\Omega/2}\\,e^{j\\Omega n}."}, "ch02_math_toolkit/04_calculus_for_signals.html#sec-2-3-3": {"tex": "\\int_a^b x(t)\\,dt \\approx T_s\\sum_{n=0}^{N-1} x[n] \\qquad \\text{(left Riemann sum)},"}, "ch02_math_toolkit/04_calculus_for_signals.html#sec-2-3-4": {"tex": "\\begin{equation*}\n\\operatorname{Var}\\big(y_{\\text{noise}}[n]\\big) = T_s^2\\,(n + 1)\\,\\sigma^2 \\quad\\Longrightarrow\\quad \\text{std} = T_s\\,\\sigma\\sqrt{n + 1} = \\sigma\\sqrt{T_s\\,t}. \\tag{2.22}\n\\end{equation*}"}, "ch02_math_toolkit/04_calculus_for_signals.html#sec-2-3-5": {"tex": "\\begin{equation*}\n\\delta_\\varepsilon(t) = \\begin{cases} 1/\\varepsilon, & |t| < \\varepsilon/2, \\\\ 0, & \\text{otherwise,} \\end{cases} \\qquad \\int_{-\\infty}^{\\infty} \\delta_\\varepsilon(t)\\,dt = 1 \\text{ for every } \\varepsilon. \\tag{2.23}\n\\end{equation*}"}, "ch02_math_toolkit/04_calculus_for_signals.html#sec-2-3-6": {"tex": "\\begin{equation*}\n\\int_a^b f(t)\\,g'(t)\\,dt = \\Big[f(t)\\,g(t)\\Big]_a^b - \\int_a^b f'(t)\\,g(t)\\,dt. \\tag{2.25}\n\\end{equation*}"}, "ch02_math_toolkit/04_calculus_for_signals.html#sec-2-3-7": {"tex": "\\begin{equation*}\n\\sum_{n=0}^{N-1} r^n = \\frac{1 - r^N}{1 - r}, \\qquad r \\ne 1, \\tag{2.28}\n\\end{equation*}"}, "ch02_math_toolkit/04_calculus_for_signals.html#sec-2-3-8": {"tex": "\\begin{equation*}\nf(x_0 + \\Delta) = f(x_0) + f'(x_0)\\,\\Delta + \\frac{f''(\\xi)}{2}\\,\\Delta^2 \\approx f(x_0) + f'(x_0)\\,\\Delta, \\tag{2.30}\n\\end{equation*}"}, "ch02_math_toolkit/05_probability_and_statistics.html#eq-2-31": {"tex": "\\begin{equation*}\nP(a < X \\le b) = \\int_a^b f_X(x)\\,dx, \\qquad f_X(x) \\ge 0, \\qquad \\int_{-\\infty}^{\\infty} f_X(x)\\,dx = 1. \\tag{2.31}\n\\end{equation*}"}, "ch02_math_toolkit/05_probability_and_statistics.html#eq-2-32": {"tex": "\\begin{equation*}\n\\sigma^2 = \\mathbb{E}[X^2 - 2\\mu X + \\mu^2] = \\mathbb{E}[X^2] - 2\\mu\\,\\mathbb{E}[X] + \\mu^2 = \\mathbb{E}[X^2] - \\mu^2 . \\tag{2.32}\n\\end{equation*}"}, "ch02_math_toolkit/05_probability_and_statistics.html#eq-2-33": {"tex": "\\begin{equation*}\n\\text{skewness} = \\mathbb{E}[Z^3], \\qquad \\text{kurtosis} = \\mathbb{E}[Z^4], \\qquad \\text{excess kurtosis} = \\mathbb{E}[Z^4] - 3. \\tag{2.33}\n\\end{equation*}"}, "ch02_math_toolkit/05_probability_and_statistics.html#eq-2-34": {"tex": "\\begin{equation*}\nf_X(x) = \\frac{1}{\\sigma\\sqrt{2\\pi}}\\,\\exp\\!\\left(-\\frac{(x - \\mu)^2}{2\\sigma^2}\\right), \\qquad X \\sim \\mathcal{N}(\\mu, \\sigma^2). \\tag{2.34}\n\\end{equation*}"}, "ch02_math_toolkit/05_probability_and_statistics.html#eq-2-35": {"tex": "\\begin{equation*}\n\\sigma_e^2 = \\int_{-\\Delta/2}^{\\Delta/2} e^2\\,\\frac{1}{\\Delta}\\,de = \\frac{1}{\\Delta}\\left[\\frac{e^3}{3}\\right]_{-\\Delta/2}^{\\Delta/2} = \\frac{1}{\\Delta}\\cdot\\frac{2}{3}\\cdot\\frac{\\Delta^3}{8} = \\frac{\\Delta^2}{12}. \\tag{2.35}\n\\end{equation*}"}, "ch02_math_toolkit/05_probability_and_statistics.html#eq-2-36": {"tex": "\\begin{equation*}\nf_X(x) = \\frac{1}{2b}\\,e^{-|x|/b}, \\qquad \\sigma^2 = 2b^2, \\qquad \\text{excess kurtosis} = 3. \\tag{2.36}\n\\end{equation*}"}, "ch02_math_toolkit/05_probability_and_statistics.html#eq-2-37": {"tex": "\\begin{equation*}\n\\operatorname{Cov}(X, Y) = \\mathbb{E}\\big[(X - \\mu_X)(Y - \\mu_Y)\\big] = \\mathbb{E}[XY] - \\mu_X\\mu_Y, \\qquad\n\\rho_{XY} = \\frac{\\operatorname{Cov}(X, Y)}{\\sigma_X\\,\\sigma_Y}. \\tag{2.37}\n\\end{equation*}"}, "ch02_math_toolkit/05_probability_and_statistics.html#eq-2-38": {"tex": "\\begin{equation*}\n\\operatorname{Var}(X + Y) = \\mathbb{E}\\big[((X - \\mu_X) + (Y - \\mu_Y))^2\\big] = \\sigma_X^2 + \\sigma_Y^2 + 2\\operatorname{Cov}(X, Y). \\tag{2.38}\n\\end{equation*}"}, "ch02_math_toolkit/05_probability_and_statistics.html#eq-2-39": {"tex": "\\begin{equation*}\n\\operatorname{Var}(\\bar{X}) = \\frac{1}{N^2}\\sum_{i=1}^{N}\\operatorname{Var}(X_i) = \\frac{1}{N^2}\\cdot N\\sigma^2 = \\frac{\\sigma^2}{N}, \\qquad \\operatorname{SE}(\\bar{X}) = \\frac{\\sigma}{\\sqrt{N}}. \\tag{2.39}\n\\end{equation*}"}, "ch02_math_toolkit/05_probability_and_statistics.html#eq-2-40": {"tex": "\\begin{equation*}\n\\bar{x} \\pm 1.96\\,\\frac{s}{\\sqrt{N}} . \\tag{2.40}\n\\end{equation*}"}, "ch02_math_toolkit/05_probability_and_statistics.html#sec-2-4-1": {"tex": "\\begin{equation*}\nP(a < X \\le b) = \\int_a^b f_X(x)\\,dx, \\qquad f_X(x) \\ge 0, \\qquad \\int_{-\\infty}^{\\infty} f_X(x)\\,dx = 1. \\tag{2.31}\n\\end{equation*}"}, "ch02_math_toolkit/05_probability_and_statistics.html#sec-2-4-2": {"tex": "\\mathbb{E}[g(X)] = \\int_{-\\infty}^{\\infty} g(x)\\,f_X(x)\\,dx ."}, "ch02_math_toolkit/05_probability_and_statistics.html#sec-2-4-3": {"tex": "\\begin{equation*}\nf_X(x) = \\frac{1}{\\sigma\\sqrt{2\\pi}}\\,\\exp\\!\\left(-\\frac{(x - \\mu)^2}{2\\sigma^2}\\right), \\qquad X \\sim \\mathcal{N}(\\mu, \\sigma^2). \\tag{2.34}\n\\end{equation*}"}, "ch02_math_toolkit/05_probability_and_statistics.html#sec-2-4-4": {"tex": "Z_N = \\frac{S_N - N\\mu}{\\sigma\\sqrt{N}}"}, "ch02_math_toolkit/05_probability_and_statistics.html#sec-2-4-5": {"tex": "\\begin{equation*}\n\\operatorname{Cov}(X, Y) = \\mathbb{E}\\big[(X - \\mu_X)(Y - \\mu_Y)\\big] = \\mathbb{E}[XY] - \\mu_X\\mu_Y, \\qquad\n\\rho_{XY} = \\frac{\\operatorname{Cov}(X, Y)}{\\sigma_X\\,\\sigma_Y}. \\tag{2.37}\n\\end{equation*}"}, "ch02_math_toolkit/05_probability_and_statistics.html#sec-2-4-6": {"tex": "\\begin{equation*}\n\\operatorname{Var}(\\bar{X}) = \\frac{1}{N^2}\\sum_{i=1}^{N}\\operatorname{Var}(X_i) = \\frac{1}{N^2}\\cdot N\\sigma^2 = \\frac{\\sigma^2}{N}, \\qquad \\operatorname{SE}(\\bar{X}) = \\frac{\\sigma}{\\sqrt{N}}. \\tag{2.39}\n\\end{equation*}"}};
